/* chronicle data chunk: cn-11 | 战国后期 前349–前222 | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-11"] = [
  { id: "cn--b349--c01", track: "cn", year: -349, yearApprox: true, dim: "culture", weight: 3, title: "驺衍至齐居稷下", summary: "阴阳五行之学入稷下，齐宣王盛礼文学游士。", detail: { background: "齐都临淄自田午立稷下，至宣王而极盛，「自如驺衍、淳于髡、田骈、接予、慎到、环渊之徒七十六人，皆赐列第，为上大夫，不治而议论」，稷下学士且数百千人。", process: "宋人驺衍（邹衍）至齐，入稷下讲论，「以迂大而闳辩」见重于诸侯之客；其「先合而后迂阔」，历齐、梁、赵，燕昭王亲执扫帚之礼先驱。", impact: "阴阳五行之说与地理「大九州」之论自此入战国思想主流，后世历数、封禅与政治地理多援其说。", figures: ["驺衍","齐宣王","淳于髡","慎到","田骈"], place: "齐都临淄稷下（今山东淄博临淄）", state: "齐国", sources: ["《史记·孟子荀卿列传》","《史记·田敬仲完世家》","《盐铁论·论儒》"], tags: ["稷下学宫","阴阳五行","战国诸子"] }, related: ["cn--b349--c02", "cn--b315--c01"] },
  { id: "cn--b349--c02", track: "cn", year: -349, yearApprox: false, dim: "culture", weight: 2, title: "齐宣王不治而议论", summary: "稷下之赐第为上大夫。", detail: { background: "田齐之君以大夫专国初立，需布衣之言以自重，故广置文学游说之士。", process: "齐宣王好文学游说之士，诸子受赐列第，皆称上大夫，不治官职而专事议论；讲论之徒且数百千人。", impact: "「不治而议论」遂成战国最著之学术体制，著书、论政与议政分途而兴。", figures: ["齐宣王","驺衍","淳于髡","接予","环渊"], place: "齐国临淄（今山东淄博临淄）", state: "齐国", sources: ["《史记·田敬仲完世家》","《史记·孟子荀卿列传》","徐干《中论·亡国》"], tags: ["稷下学宫","学术自由","战国教育"] }, related: ["cn--b349--c01", "cn--b315--c01"] },
  { id: "cn--b348--i01", track: "cn", year: -348, yearApprox: false, dim: "institution", weight: 3, title: "秦初为赋", summary: "秦按户出赋，军国之费始有常科。", detail: { background: "商鞅行县制、编伍之后，国用须有常出，军赋乃别于田租而立。", process: "秦孝公十四年（前348）「初为赋」。说者或以户赋、或以军赋释之，赋随户口而科，故民数之核愈严。", impact: "户赋之立，使秦之征发以户口为本，为后世以丁口计赋者所自出。", figures: ["商鞅","秦孝公"], place: "秦国咸阳（今陕西咸阳）", state: "秦国", sources: ["《史记·秦本纪》","《通典·食货四》"], tags: ["赋税","秦制","商鞅变法"] }, related: ["cn--b309--i02", "cn--b336--e01"] },
  { id: "cn--b344--p01", track: "cn", year: -344, yearApprox: true, dim: "politics", weight: 4, title: "魏惠王逢泽称王", summary: "魏会十二诸侯于逢泽，宋服，魏始僭王。", detail: { background: "魏惠王自霸越于泗上，其地东败于齐，故欲以会盟自崇其位。", process: "前344年（一说前343年），魏惠大会鲁、卫、宋、郑诸君于逢泽（今河南郑州南），车服拟于天子，因朝周显王。或曰惠施为之谋。", impact: "战国称王自此风渐开，周之名义愈轻；次年齐魏有徐州相王之局。", figures: ["魏惠王","惠施","周显王"], place: "魏逢泽（今河南郑州南）", state: "魏国", sources: ["《竹书纪年》（《水经·渠水注》引）","《史记·魏世家》","杨宽《战国史》附录《战国大事年表》"], tags: ["称王","会盟","战国外交"] }, related: ["cn--b334--p01", "cn--b323--p01"] },
  { id: "cn--b341--f01", track: "cn", year: -341, yearApprox: true, dim: "figure", weight: 2, title: "申不害卒于韩", summary: "韩相十五年，术治之学随人以息。", detail: { background: "申不害者，郑之贱臣也，以学术说韩昭侯，遂相韩。", process: "前341年（韩昭侯二十五年）申不害卒，昭侯之世亦寻殂。不害相韩十五年，内修政教，应对外诸侯。", impact: "其学本黄老而主刑名，以「术」为一派，与秦晋之法、齐国之论并立，《汉书·艺文志》著录《申子》。", figures: ["申不害","韩昭侯"], place: "韩国阳翟（今河南禹州）", state: "韩国", sources: ["《史记·老子韩非列传》","《汉书·艺文志》","《韩非子·定法》"], tags: ["法家","术治","申子"] }, related: ["cn--b341--m01"] },
  { id: "cn--b340--m01", track: "cn", year: -340, yearApprox: false, dim: "military", weight: 3, title: "商鞅袭虏魏公子卬", summary: "以故情绐魏将，因袭其军，魏师大坏。", detail: { background: "马陵之后魏兵数困，秦孝公使卫鞅将兵击魏，魏使公子卬将而应之。", process: "前340年卫鞅与魏军相遇，使人绐公子卬以昔时之好而约为会，伏甲击而虏之，因乘乱攻魏师，魏败。", impact: "魏既丧其质将，乃尽河西之地而迁都大梁，秦之东向门户自是启。", figures: ["商鞅","魏公子卬","秦孝公"], place: "魏西河（今陕西东部黄河西岸）", state: "秦、魏", sources: ["《史记·商君列传》","《史记·魏世家》"], tags: ["河西","诈袭","秦魏"] }, related: ["cn--b341--m01", "cn--b340--p01"] },
  { id: "cn--b340--p01", track: "cn", year: -340, yearApprox: false, dim: "politics", weight: 3, title: "秦封卫鞅于商於", summary: "以於、商十五邑为封，号曰商君。", detail: { background: "卫鞅既破魏而还，秦孝公以商於之地十五邑封之。", process: "前340年秦封鞅於、商十五邑，号为商君；赵良面折之，谓其「凌轹公族」而多怨。", impact: "商君之号由此而传，封邑之复行于秦，与商邑之兴废俱尽于孝公之世。", figures: ["商鞅","秦孝公","赵良"], place: "秦商於（今陕西商洛至河南淅川一带）", state: "秦国", sources: ["《史记·商君列传》","《战国策·秦策一》"], tags: ["封君","商於","商鞅"] }, related: ["cn--b338--f01", "cn--b340--m01"] },
  { id: "cn--b338--p02", track: "cn", year: -338, yearApprox: false, dim: "politics", weight: 4, title: "秦孝公卒惠文君立", summary: "新君即位，诸公子怨商君者得志。", detail: { background: "孝公任用卫鞅二十四年，法令已成而怨望亦积；太子尝犯法，师傅公子虔、公孙贾被刑。", process: "前338年孝公卒，太子驷立，是为惠文君。公子虔之属告商君欲反，发吏捕之。", impact: "惠文君车裂商君而终不改其法，秦之治制自此不与人主俱亡。", figures: ["秦惠文王","秦孝公","公子虔","商鞅"], place: "秦国咸阳（今陕西咸阳）", state: "秦国", sources: ["《史记·秦本纪》","《史记·商君列传》","《史记·李斯列传》"], tags: ["君位更替","秦制","商鞅"] }, related: ["cn--b338--f01", "cn--b340--p01"] },
  { id: "cn--b338--f01", track: "cn", year: -338, yearApprox: false, dim: "figure", weight: 4, title: "商鞅死于彤", summary: "出关无验，归商邑发邑兵，战死于彤。", detail: { background: "商君之封既成，赵良已早为之兆；孝公卒而新怨并作。", process: "前338年商鞅亡奔魏，魏不受，复归秦，之商、於邑之封，发邑兵北出击郑（郑县）。秦发兵攻而杀之于彤（今陕西大荔），「秦惠王车裂商君以徇，遂灭商君之家」。", impact: "商君虽死，「秦法未败」，故论秦制者必自鞅始；韩非所谓「及孝公、商君死，惠王即位，秦法未败也」于此可见。", figures: ["商鞅","秦惠文王","公子虔","赵良"], place: "秦彤、郑县（今陕西大荔、华州一带）", state: "秦国", sources: ["《史记·商君列传》","《史记·秦本纪》","《韩非子·定法》"], tags: ["商鞅之死","法家","秦制"] }, related: ["cn--b338--p02", "cn--b340--p01"] },
  { id: "cn--b337--c01", track: "cn", year: -337, yearApprox: true, dim: "culture", weight: 3, title: "苏秦始将连横", summary: "说秦惠王，书十上不纳，归发书。", detail: { background: "《战国策》载苏秦者，洛邑之人，始以「连横」之说干秦惠王，欲并天下。", process: "前337年（年次无可考，据《秦策》所记系之）书十上而说不行。黑貂之裘弊，黄金百斤尽，归至家，妻不下紝，嫂不为炊。乃夜发书，得《太公阴符》之谋，伏而诵之，引锥自刺其股。", impact: "《秦策》一章为战国纵横家文字之最著者，其「抵掌而谈」「天下服」之语亦多夸饰；1973年马王堆帛书《战国纵横家书》出土，苏秦事迹之年代多异于《史记》。", figures: ["苏秦","秦惠文王"], place: "秦咸阳、洛邑（今陕西咸阳、河南洛阳）", state: "秦、周", sources: ["《战国策·秦策一》","《史记·苏秦列传》","马王堆汉墓帛书《战国纵横家书》释文（文物出版社1976年）"], tags: ["纵横家","连横","战国策"] }, related: ["cn--b334--p01", "cn--b285--f01"] },
  { id: "cn--b336--e01", track: "cn", year: -336, yearApprox: false, dim: "economy", weight: 3, title: "秦初行钱", summary: "惠文君二年铸钱行之，秦币制见于纪。", detail: { background: "秦自献公「初行为市」，孝公用商君重课耕战，山泽钱布之利渐归公上。", process: "前336年（秦惠文君二年）「初行钱」，事见《史记·秦本纪》。秦钱圜而方孔，名曰半两，铸钱之政自此不废。", impact: "秦之国币自行于关中，商贾之利与军国之需相为表里，为后来「一量衡、一币制」之先声。", figures: ["秦惠文王"], place: "秦国咸阳（今陕西咸阳）", state: "秦国", sources: ["《史记·秦本纪》","《史记·平准书》","《史记·六国年表》"], tags: ["币制","战国经济","秦制"] }, related: ["cn--b348--i01", "cn--b330--p01"] },
  { id: "cn--b334--p01", track: "cn", year: -334, yearApprox: true, dim: "politics", weight: 4, title: "徐州相王", summary: "齐、魏二君以会盟相加王号，魏先倡之。", detail: { background: "马陵新败之后，魏之霸已挫，齐遂为东方最强；徐、泗之间须有主盟之名。", process: "前334年（《史记》书齐威王与魏惠王会于徐州而相王；《竹书纪年》与近世考订则谓其礼为魏率泗上诸侯朝齐，两名目与年次并存，故系年从约）二君以王号相加，因相与结好。", impact: "二国之号自会盟而定，称王之风遂遍于七雄；周之名分至是而尽，后此前323年五国相王循其例而益溷。", figures: ["齐威王","魏惠王","惠施"], place: "徐州（今山东滕州南，一说在今江苏邳州）", state: "齐、魏", sources: ["《史记·魏世家》","《史记·田敬仲完世家》","《史记·六国年表》","《竹书纪年》（辑本）"], tags: ["徐州相王","称王","会盟"] }, related: ["cn--b344--p01", "cn--b323--p01"] },
  { id: "cn--b330--p01", track: "cn", year: -330, yearApprox: false, dim: "politics", weight: 3, title: "魏纳上郡十五县", summary: "魏尽入上郡于秦，河西、上郡遂并为秦。", detail: { background: "魏自马陵再败，东地益蹙，秦复连岁东伐，魏无以守河。", process: "前330年（秦惠文君八年）魏尽纳上郡十五县于秦，河西、上郡之地并为秦有，魏去西河而守洛水。", impact: "秦东以河为固，关门之外不复有魏之锐师；魏之封域自此东移于大梁。", figures: ["魏惠王","秦惠文王"], place: "魏上郡（今陕西延安、榆林一带）", state: "魏、秦", sources: ["《史记·秦本纪》","《史记·魏世家》","《史记·六国年表》"], tags: ["魏国丧地","上郡","秦国东向"] }, related: ["cn--b340--m01", "cn--b336--e01"] },
  { id: "cn--b330--s01", track: "cn", year: -330, yearApprox: true, dim: "science", weight: 3, title: "后期墨家治名辩光学", summary: "《墨经》诸篇约编于此时，验名理与光力。", detail: { background: "墨子之后，「相里勤之弟子，五侯之徒，南方之墨者苦获、己齿、邓陵子之属，俱诵《墨经》而倍谲不同，相谓别墨」，以坚白同异之辩相訾。", process: "前四世纪末至前三世纪，后期墨家先后编定《经》上下、《经说》上下、《大取》《小取》诸篇，论小孔成像、影之成因，定义力、动、久、宇之属。", impact: "其名学与光学、力学之识为先秦至精者，与惠施历物十事、公孙龙诸题相激成风；秦汉之后其学几绝。", figures: ["墨翟","相里勤","惠施","公孙龙"], place: "宋、鲁、齐、楚之郊（墨者散游，无定所）", state: "诸国", sources: ["《庄子·天下》","《墨子·经说下》","谭戒甫《墨辩发微》"], tags: ["墨家","名辩","光学"] }, related: ["cn--b349--c01", "cn--b323--p01"] },
  { id: "cn--b328--p01", track: "cn", year: -328, yearApprox: true, dim: "politics", weight: 3, title: "张仪始相秦", summary: "魏人张仪入秦为相，连横之谋自此发。", detail: { background: "张仪者魏人，尝与苏秦同事鬼谷先生以学游说之术；苏秦约从之后，秦欲散其约。", process: "前328年（秦惠文君十年）张仪相秦，秦使公子华、张仪围魏蒲阳，因使张仪说魏而纳上郡。", impact: "秦之以「连横」解「合从」自张仪始，山东之国数合数离，其势益分。", figures: ["张仪","秦惠文王","公孙衍"], place: "秦国咸阳（今陕西咸阳）", state: "秦国", sources: ["《史记·张仪列传》","《史记·秦本纪》","《战国策·秦策一》"], tags: ["纵横家","连横","相邦"] }, related: ["cn--b330--p01", "cn--b337--c01"] },
  { id: "cn--b325--p01", track: "cn", year: -325, yearApprox: false, dim: "politics", weight: 3, title: "秦惠文君自立为王", summary: "惠文君十四年更号为王，与山东并尊。", detail: { background: "魏、齐既以相王而僭号，秦虽远在西垂，亦耻居公位。", process: "前325年（秦惠文君十四年）四月，惠文君初称为王；明年（前324年）改元，是为更元元年。", impact: "秦与山东诸侯敌体而王，周之名义愈轻；明年遂改元建号，秦之制命渐有其统。", figures: ["秦惠文王","张仪"], place: "秦国咸阳（今陕西咸阳）", state: "秦国", sources: ["《史记·秦本纪》","《史记·六国年表》","杨宽《战国史》"], tags: ["称王","名分","秦制"] }, related: ["cn--b344--p01", "cn--b334--p01"] },
  { id: "cn--b323--p01", track: "cn", year: -323, yearApprox: true, dim: "politics", weight: 3, title: "公孙衍倡五国相王", summary: "魏、韩、赵、燕、中山更相尊王。", detail: { background: "公孙衍（犀首）与张仪争宠于秦，出奔入魏，以「合从」相王之谋抗连横。", process: "前323年（年有前324、前323两说）公孙衍主魏、韩、赵、燕、中山五国更相尊王，中山与诸侯之列；齐王耻中山之卑而欲伐之。赵武灵王独辞其号。", impact: "名分之乱自大国延于小国，「一怒而诸侯惧」之喻由此而兴，纵横之家遂擅天下之权。", figures: ["公孙衍","魏惠王","赵武灵王","张仪"], place: "魏大梁（今河南开封）", state: "魏、韩、赵、燕、中山", sources: ["《史记·赵世家》","《史记·魏世家》","《战国策·中山策》","《孟子·滕文公下》"], tags: ["五国相王","公孙衍","合从"] }, related: ["cn--b328--p01", "cn--b334--p01"] },
  { id: "cn--b320--f01", track: "cn", year: -320, yearApprox: true, dim: "figure", weight: 2, title: "张仪去秦相魏", summary: "仪以连横说魏王，魏不用，乃相魏。", detail: { background: "秦惠王以张仪之计取陕、取上郡，仪复欲因魏以制楚、齐。", process: "约前320年张仪离秦入魏，为魏之相，欲道魏王先事秦而天下可从。魏襄王不能用其谋。", impact: "张仪虽去秦，秦不辍其连横之策，其后樗里疾、甘茂、魏冉皆仍其成规。", figures: ["张仪","魏襄王"], place: "魏大梁（今河南开封）", state: "魏、秦", sources: ["《史记·张仪列传》","《战国策·魏策》","杨宽《战国史》附录年表"], tags: ["纵横家","张仪","魏国"] }, related: ["cn--b328--p01", "cn--b309--f01"] },
  { id: "cn--b318--m01", track: "cn", year: -318, yearApprox: true, dim: "military", weight: 3, title: "五国攻秦至函谷关", summary: "楚、魏、赵、韩、燕共攻秦，至关而不克。", detail: { background: "公孙衍以「合从」之力谋秦，楚怀王为纵长以主其事。", process: "前318年（《秦本纪》系于更元七年，亦有前317年之说）楚、魏、赵、韩、燕五国之兵共攻秦，至函谷关而秦出兵逆击，诸侯之师皆败走。", impact: "五国之兵聚于关下而不能入，山东之国「心异而兵不合」之病自此屡见。", figures: ["楚怀王","公孙衍","秦惠文王"], place: "秦函谷关（今河南灵宝）", state: "秦、楚、魏、赵、韩、燕", sources: ["《史记·秦本纪》","《史记·六国年表》","《史记·楚世家》"], tags: ["合从","函谷关","五国攻秦"] }, related: ["cn--b323--p01", "cn--b317--m01"] },
  { id: "cn--b318--p01", track: "cn", year: -318, yearApprox: true, dim: "politics", weight: 3, title: "燕王哙让国于子之", summary: "哙以国为让于相子之，国事皆断于子之。", detail: { background: "燕王哙年老，信任其相子之。鹿毛寿之属因以「唐尧让许由」之说进之，欲以让名重子之。", process: "前318年前后（燕王哙三年，年有先后两说）燕王哙尽以国事属子之，子之南面行王事，而哙老不再听政。", impact: "燕国因内裂而大乱，太子平与将军市被起而不克，齐宣王遂乘其敝而入燕。", figures: ["燕王哙","子之","鹿毛寿","太子平"], place: "燕都（今北京房山、河北易县一带）", state: "燕国", sources: ["《史记·燕召公世家》","《战国策·燕策一》","《资治通鉴》卷三"], tags: ["燕国","让国","内乱"] }, related: ["cn--b314--m01", "cn--b311--p02"] },
  { id: "cn--b317--m01", track: "cn", year: -317, yearApprox: true, dim: "military", weight: 3, title: "秦败韩赵于修鱼", summary: "韩、赵攻秦，秦逆击之于修鱼，斩首八万。", detail: { background: "五国攻秦既退，韩、赵复独出师以争。", process: "前317年（《秦本纪》更元八年，年月或有异同）韩、赵之师西向，秦与战于修鱼（今河南原阳西南），韩、赵之众大奔。", impact: "秦兵既折山东之锐于河北，三晋不复敢以全力西向。", figures: ["秦惠文王","韩公仲","赵武灵王"], place: "韩、赵修鱼（今河南原阳西南）", state: "秦、韩、赵", sources: ["《史记·秦本纪》","《史记·韩世家》","《史记·六国年表》"], tags: ["战国战役","三晋","秦国东向"] }, related: ["cn--b318--m01", "cn--b316--p01"] },
  { id: "cn--b316--p01", track: "cn", year: -316, yearApprox: false, dim: "politics", weight: 5, title: "秦司马错灭蜀取苴、巴", summary: "司马错自石牛道伐蜀，执蜀王而遂定巴、苴。", detail: { background: "蜀王与苴侯构怨，苴侯奔巴，巴、蜀皆告急于秦。秦惠王欲伐蜀，张仪以为不如「下兵三川」以挟天子，司马错独谓「得蜀则得楚，楚亡则天下并矣」，惠王卒从错策。", process: "前316年秋，秦使司马错、都尉墨率众从石牛道入蜀，与蜀王战于葭萌（今四川昭化），蜀王败走，死于丹棱（一说武阳），秦遂取蜀；因执苴侯于卤（今四川巴中一带），又降巴。", impact: "秦并有巴、蜀，得粮谷、盐铁之饶，居楚之上流；《秦本纪》所谓「蜀既属秦，秦以益强，富厚，轻诸侯」即指此。蜀之入秦，为日后并天下与南图百越之本。", figures: ["司马错","张仪","秦惠文王","蜀王","都尉墨"], place: "蜀葭萌、成都（今四川广元、成都）", state: "秦、蜀、巴、苴", sources: ["《华阳国志·蜀志》","《史记·秦本纪》","《战国策·秦策一》","《史记·张仪列传》"], tags: ["灭蜀","巴蜀","秦并天下"] }, related: ["cn--b316--i01", "cn--b317--m01"] },
  { id: "cn--b316--i01", track: "cn", year: -316, yearApprox: true, dim: "institution", weight: 2, title: "秦置蜀守，徙民实蜀", summary: "秦贬蜀王为侯，置守而徙秦万家于蜀。", detail: { background: "秦取蜀后，以蜀之远而俗异，封建与置守之议再反覆。", process: "前316年后（年不可密，依《华阳国志》）秦贬蜀王曰蜀侯，以公子通为蜀侯，张若为蜀守，「乃移秦家万家于蜀」，并取巴地置巴郡。", impact: "郡守之制行于新得之蜀，移民实边之策自此为秦之常法。", figures: ["张仪","秦惠文王","张若","司马错"], place: "秦蜀郡（今四川成都）", state: "秦国", sources: ["《华阳国志·蜀志》","《史记·秦本纪》","《史记·楚世家》（巴、蜀之文）"], tags: ["郡县","移民实边","巴蜀"] }, related: ["cn--b316--p01", "cn--b272--i01"] },
  { id: "cn--b315--c01", track: "cn", year: -315, yearApprox: true, dim: "culture", weight: 2, title: "稷下蓄黄老刑名", summary: "慎到、接予之徒在齐，贵因循而尚公。", detail: { background: "稷下并蓄众家，道、法、名、墨同处而议，不专主一说。", process: "前315年前后（其年至为约略，稷下诸子往还之岁本无明文）赵之慎到与接予在齐讲论，贵因循而尚公，言官不择人而治、因民之性而立教；其书后世散佚，今存者出辑本。", impact: "黄老与刑名之说由齐入于三晋与秦，后世所谓无为而治与法不阿贵二义，皆可于此见其端。", figures: ["慎到","接予","驺衍"], place: "齐都临淄稷下（今山东淄博临淄）", state: "齐国", sources: ["《史记·孟子荀卿列传》","《慎子》（辑本）","《荀子·非十二子》","《庄子·天下》"], tags: ["稷下学宫","黄老","刑名"] }, related: ["cn--b349--c01", "cn--b349--c02"] },
  { id: "cn--b314--m01", track: "cn", year: -314, yearApprox: true, dim: "military", weight: 4, title: "齐宣王因乱破燕", summary: "齐乘燕内乱入其国，杀哙与子之，取府库。", detail: { background: "燕王哙既以国属子之，太子平与将军市被聚徒攻子之，不能下而相攻击，累日不解，国中扰乱，百姓恫怨。", process: "前314年（一说前315年）齐以匡章将五都之兵、因北地之众以伐燕；燕士卒不战、城门不闭，齐遂入燕都，杀燕王哙，诛子之，取燕之府库。诸侯谋救燕，燕人复叛，齐乃引兵而还。", impact: "齐以万乘之国，旬日而举一燕，卒不能守，燕人共立昭王；燕昭王卑身厚币以招贤者，专以报齐为事，前284年五国之师所自起。", figures: ["齐宣王","匡章","燕王哙","子之","孟子"], place: "燕都蓟（今北京）", state: "齐、燕", sources: ["《史记·燕召公世家》","《史记·田敬仲完世家》","《孟子·梁惠王下》","《资治通鉴》卷三（伐燕之年《纪年》与《年表》差一年，故系年从近似）"], tags: ["齐破燕","匡章","燕昭王"] }, related: ["cn--b318--p01", "cn--b312--m01"] },
  { id: "cn--b313--p01", track: "cn", year: -313, yearApprox: true, dim: "politics", weight: 3, title: "张仪绐楚，许商於六百里", summary: "仪说楚怀王闭关绝齐，以六百里商於之地为赂。", detail: { background: "楚怀王与齐宣王从亲，秦患之，张仪请使楚而解其约。", process: "前313年（年次自《楚世家》《张仪列传》推，异说不一）张仪至郢，许以商於之地六百里，劝楚闭关而绝齐使之路。楚怀王不与群臣谋，遂绝齐；使人受地，仪称「有邑六里」。", impact: "楚怒而举兵西向，丹阳、蓝田两败，汉中遂入于秦，合从之势大坏。", figures: ["张仪","楚怀王","屈匄","陈轸"], place: "楚郢（今湖北荆州北）", state: "楚、秦", sources: ["《史记·楚世家》","《史记·张仪列传》","《战国策·秦策二》"], tags: ["连横","商於","楚齐绝"] }, related: ["cn--b312--m01", "cn--b328--p01"] },
  { id: "cn--b312--m01", track: "cn", year: -312, yearApprox: true, dim: "military", weight: 4, title: "丹阳之战，秦取汉中", summary: "楚怒而伐秦，大败于丹阳，大将屈匄被虏。", detail: { background: "楚怀王以受绐而怒，不计齐之未可恃，悉兵西向。", process: "前312年（《六国年表》《楚世家》所载年月有出入）楚、秦遇于丹阳（今湖北秭归东至河南丹水之阳，地望有二说），楚师大败，秦虏其大将军屈匄；遂取楚汉中地，置汉中郡。《楚世家》、《秦本纪》、《六国年表》所记斩首、所虏人数多寡互异，各方记载差异较大。", impact: "楚之精锐与汉中之地俱丧，秦得由武关以临郢，楚之国势自此不振。", figures: ["楚怀王","屈匄","魏章","甘茂","秦惠文王"], place: "丹阳、汉中（今陕南、鄂西北）", state: "秦、楚", sources: ["《史记·楚世家》","《史记·秦本纪》","《史记·六国年表》","《战国策·楚策二》"], tags: ["丹阳","汉中","秦楚"] }, related: ["cn--b312--m02", "cn--b313--p01"] },
  { id: "cn--b312--m02", track: "cn", year: -312, yearApprox: true, dim: "military", weight: 3, title: "楚蓝田之伐与韩、魏之乘", summary: "楚悉兵深入伐秦，战蓝田不利，韩、魏乘其后。", detail: { background: "丹阳既败，楚怀王「乃悉国兵复袭秦，战于蓝田」。", process: "前312年（《楚世家》《秦本纪》异）楚军西入武关，与秦战于蓝田（今陕西蓝田），楚不利；韩、魏闻而东袭楚，至邓（今湖北襄樊北），楚乃引兵而归。", impact: "楚既丧汉中，又为韩、魏所乘，乃复东与齐平；秦之连横始得志于南方。", figures: ["楚怀王","秦惠文王","韩襄王","魏襄王"], place: "秦蓝田（今陕西蓝田）", state: "楚、秦、韩、魏", sources: ["《史记·楚世家》","《史记·秦本纪》","《史记·六国年表》"], tags: ["蓝田","楚衰","韩魏乘虚"] }, related: ["cn--b312--m01", "cn--b303--f01"] },
  { id: "cn--b311--p02", track: "cn", year: -311, yearApprox: false, dim: "politics", weight: 3, title: "秦武王立，逐张仪", summary: "惠王卒，武王即位；素不悦张仪，仪惧而出奔。", detail: { background: "秦惠王卒于前311年，太子荡立。武王为公子时已不与张仪相得，群臣亦多疾之。", process: "前311年武王即位，「群臣争言仪之短」，张仪恐诛，乃以「为秦计」之说请使魏而诱齐伐魏以并其兵，卒去秦相魏。", impact: "仪去而秦之连横不废；武王益欲东向三川，数年之后遂有宜阳之役。", figures: ["秦武王","张仪","秦惠文王","甘茂"], place: "秦国咸阳（今陕西咸阳）", state: "秦国", sources: ["《史记·秦本纪》","《史记·张仪列传》"], tags: ["君位更替","张仪","秦国外交"] }, related: ["cn--b309--f01", "cn--b307--p01"] },
  { id: "cn--b309--f01", track: "cn", year: -309, yearApprox: true, dim: "figure", weight: 2, title: "张仪卒于魏", summary: "去秦相魏，未几而卒，连横之策告终。", detail: { background: "张仪在秦以连横之说得惠文、武两王之任，及武王立而见逐，遂去秦而相魏。", process: "前309年前后张仪卒于魏（《张仪列传》系其卒于魏，岁次说者有异）；其始以商於六百里之地绐楚怀王，终以魏为一身之归。", impact: "仪之死在秦拔宜阳、武王入周之岁，连横之局随之而变；苏秦、张仪之事诸国之载不同，太史公已著其疑，帛书《战国纵横家书》出而苏秦之年代复晚于《史记》所次。", figures: ["张仪"], place: "魏都大梁（今河南开封）", state: "魏国", sources: ["《史记·张仪列传》","《史记·六国年表》","马王堆帛书《战国纵横家书》整理本","钱穆《先秦诸子系年》"], tags: ["连横","纵横家","张仪"] }, related: ["cn--b320--f01", "cn--b328--p01"] },
  { id: "cn--b309--i01", track: "cn", year: -309, yearApprox: true, dim: "institution", weight: 2, title: "以谷石计俸与守令之秩", summary: "战国吏禄以石数差秩，秦简犹见其制。", detail: { background: "世卿之禄出于邑，战国之吏受禄于官，故秩以谷石之差为等。", process: "战国中世以后，秦、三晋之吏禄多以「石」数相别，自佐史至令长大另有甲、盾、币之赐；其详制见于睡虎地所出秦简，而彼简写定于战国之末，可以推见此前之渐。", impact: "以石计秩，使官人之升降可校而上计可行，后世之秩品、俸钱由此出；策名委质之礼遂为文法之吏所代。", figures: ["秦献公"], place: "秦与三晋之县廷（今陕西、山西、河南）", state: "秦、三晋", sources: ["睡虎地秦墓竹简整理小组《睡虎地秦墓竹简》","《史记·秦本纪》","《荀子·强国》","杨宽《战国史》"], tags: ["俸禄","上计","官制"] }, related: ["cn--b348--i01", "cn--b309--i02"] },
  { id: "cn--b309--i02", track: "cn", year: -309, yearApprox: false, dim: "institution", weight: 3, title: "秦初置丞相", summary: "武王二年置丞相，樗里疾、甘茂为左右。", detail: { background: "秦自孝公用卫鞅为大良造，掌军国之事；武王即位，欲开三川，官名稍与三晋相近。", process: "前309年（秦武王二年）初置丞相之官，以樗里疾、甘茂为左右丞相；相邦、丞相两名在秦之器铭与史文并见，其职为文吏之长，而兵符别有所在。", impact: "丞相自此为秦之定制，汉袭不改；此后入秦而居相位者，如范雎、吕不韦、李斯，皆循此途。", figures: ["秦武王","樗里疾","甘茂"], place: "秦都咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·秦本纪》","《史记·樗里子甘茂列传》","《汉书·百官公卿表》"], tags: ["丞相","官制","秦国"] }, related: ["cn--b348--i01", "cn--b311--p02"] },
  { id: "cn--b308--m01", track: "cn", year: -308, yearApprox: true, dim: "military", weight: 3, title: "甘茂攻宜阳未下", summary: "五月不拔，武王欲休兵，茂引息壤为约。", detail: { background: "武王欲通车三川以临周室，使甘茂借道于魏而伐韩之宜阳，宜阳为韩之要隘。", process: "前308年起攻宜阳，历五月而不能拔，士疲粮阻，武王欲罢兵；甘茂引乐羊伐中山而魏文侯示以息壤之记为喻，请必竟其功，王复益兵遣之。", impact: "一城之役几至中变，秦之君臣相疑自此始；甘茂遂以是得罪于向寿、公孙奭之属，其后奔齐。", figures: ["甘茂","秦武王","向寿"], place: "韩宜阳（今河南宜阳西）", state: "秦、韩", sources: ["《史记·樗里子甘茂列传》","《史记·秦本纪》","《战国策·秦策二》"], tags: ["宜阳","攻坚","客卿"] }, related: ["cn--b307--m01", "cn--b309--i02"] },
  { id: "cn--b307--m01", track: "cn", year: -307, yearApprox: true, dim: "military", weight: 3, title: "秦拔宜阳通三川", summary: "宜阳既拔，韩之援后至，三川之路遂开。", detail: { background: "宜阳城内蓄委积，外接韩之南阳，楚之救与韩之援相属，故秦攻之经年。", process: "前307年甘茂复力攻而拔宜阳；《史记·秦本纪》书斩首六万，他篇所记多寡不侔，旧说疑其过当，今两存其文而不取一定之数。韩之救兵后至，武王遂因道入周。", impact: "秦得宜阳则三川之路通，韩之都与南阳隔绝；武王旋死而蜀、汉之谋不辍，昭王因之东向益急。", figures: ["甘茂","向寿","公仲侈"], place: "韩宜阳（今河南宜阳西）", state: "秦、韩", sources: ["《史记·秦本纪》","《史记·樗里子甘茂列传》","《战国策·秦策二》","杨宽《战国史》"], tags: ["宜阳","三川","战国战争"] }, related: ["cn--b308--m01", "cn--b307--p01"] },
  { id: "cn--b307--p01", track: "cn", year: -307, yearApprox: false, dim: "politics", weight: 4, title: "秦武王举鼎而死", summary: "与力士举鼎绝膑，年二十三，无嗣。", detail: { background: "武王有力而好戏，力士任鄙、乌获、孟说皆至大官；既通三川，欲观周之九鼎，轻万乘之重。", process: "前307年武王与孟说举鼎而绝膑，八月死（《秦本纪》），年二十三；诸异母弟争立，赵武灵王送公子稷之在燕者入秦，魏冉以兵为内应，遂立昭王。", impact: "一死而国统几乱，宣太后与穰侯之政由是而起；秦之东向遂有后四十年之续。", figures: ["秦武王","孟说","秦昭王","魏冉"], place: "周都洛阳（今河南洛阳）", state: "秦国", sources: ["《史记·秦本纪》","《史记·穰侯列传》","《史记·赵世家》"], tags: ["秦武王","君位继承","九鼎"] }, related: ["cn--b311--p02", "cn--b306--p01"] },
  { id: "cn--b307--m02", track: "cn", year: -307, yearApprox: true, dim: "military", weight: 4, title: "赵武灵王命卒习骑射", summary: "十九年召楼缓议服，易胡服以习骑射。", detail: { background: "赵东邻齐、宋，中有中山，北接林胡、楼烦，车战之利不给于山泽之间。", process: "前307年（赵武灵王十九年）召楼缓议易服于公室，改宽博之衣为短便于骑，群臣难之，公子成始亦辞疾，武王亲往喻之，乃下令而习骑射。", impact: "边兵之制自车而骑，赵遂得云中、雁门、代北之地，秦、燕后亦仿其法；论战国骑兵之盛者多原于此。", figures: ["赵武灵王","楼缓","公子成"], place: "赵都邯郸与西北边（今河北邯郸、晋北）", state: "赵国", sources: ["《史记·赵世家》","《战国策·赵策二》","钱穆《先秦诸子系年》"], tags: ["胡服骑射","兵制","赵国"] }, related: ["cn--b306--m01", "cn--b307--p01"] },
  { id: "cn--b306--p01", track: "cn", year: -306, yearApprox: true, dim: "politics", weight: 4, title: "宣太后与穰侯用事", summary: "立昭王，太后临事，魏冉以兵权重。", detail: { background: "惠文后欲立他公子，诸弟争位；公子稷质于燕，赵送之，秦内有兵而外有援。", process: "前306年前后昭王得立，其母宣太后（楚之芈八子）任事，以魏冉为将、封于穰，号穰侯；华阳君芈戎、高陵君、泾阳君并贵，所谓四贵者出其门。", impact: "昭王前四十年之政多出后、侯之门，「四贵」之富拟于公室，至范雎说王而权始还；秦之东取魏、南破楚，皆在此局中。", figures: ["秦昭王","宣太后","魏冉"], place: "秦都咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·秦本纪》","《史记·穰侯列传》","《史记·范雎蔡泽列传》"], tags: ["宣太后","穰侯","外戚"] }, related: ["cn--b307--p01", "cn--b300--i01"] },
  { id: "cn--b306--m01", track: "cn", year: -306, yearApprox: true, dim: "military", weight: 3, title: "赵西略胡地至榆中", summary: "骑射既行，赵北拓林胡、楼烦之境。", detail: { background: "胡服之令既行，赵有骑兵而患无马与牧地，中山犹在腹心。", process: "前306年前后赵武灵王西略胡地，至榆中（今内蒙古鄂尔多斯东南），林胡、楼烦之属以马与地应之；其置郡设守之年次史无明文，说者据《赵世家》推定。", impact: "赵北境遂阻河而守，骑射之源日足，中山之势日孤；其后云中、雁门、代三郡与并河之长城，皆基于此数岁之略地。", figures: ["赵武灵王"], place: "赵西北边榆中（今内蒙古鄂尔多斯一带）", state: "赵国", sources: ["《史记·赵世家》","《史记·匈奴列传》","杨宽《战国史》"], tags: ["林胡","边郡","骑射"] }, related: ["cn--b307--m02", "cn--b306--x01"] },
  { id: "cn--b306--x01", track: "cn", year: -306, yearApprox: true, dim: "explore", weight: 2, title: "楚东取江、越之地", summary: "乘越之乱，楚境东至浙江之滨。", detail: { background: "越自句践以后，中国之交渐北，楚之东境日迫；而越之诸子争立，内乱不已。", process: "前306年前后楚乘越乱东进，尽取江、淮以南至于浙江之地，越之君族散处江南，降称君长；说者或系于楚之先世，年次异同，故约略书之。", impact: "吴、越旧地入楚，稻、帛、铜、锡与海盐之利归焉，楚之东境始与海近；越人之君长后复见于会稽、浙江之南。", figures: ["楚怀王"], place: "楚之江东（今江苏南部、浙江北部）", state: "楚国", sources: ["《史记·楚世家》","《韩非子·说疑》","《竹书纪年》（辑本）","杨宽《战国史》"], tags: ["百越","江东","疆域"] }, related: ["cn--b304--p01", "cn--b306--m01"] },
  { id: "cn--b304--p01", track: "cn", year: -304, yearApprox: true, dim: "politics", weight: 3, title: "秦楚会于黄棘", summary: "秦与楚地以结之，楚背齐而合秦。", detail: { background: "丹阳、蓝田再败之后，楚外失齐援，秦欲离三国之从而以地市楚。", process: "前304年楚怀王与秦昭王会于黄棘（今河南南阳境），秦归楚地以结之；《楚世家》于所还上庸与汉中旁近之文互见，所载有差池。", impact: "楚由是绝齐而合秦，齐、韩、魏以为背纵而兴师；一岁之间楚以一身居两横之下，国势遂蹙。", figures: ["楚怀王","秦昭王","太子横"], place: "楚黄棘（今河南南阳一带）", state: "楚、秦", sources: ["《史记·楚世家》","《史记·六国年表》","《战国策·楚策》"], tags: ["黄棘","合纵连横","楚国外交"] }, related: ["cn--b312--m01", "cn--b303--p01"] },
  { id: "cn--b303--p01", track: "cn", year: -303, yearApprox: false, dim: "politics", weight: 3, title: "三国共伐楚", summary: "齐韩魏以楚与秦合而伐之，楚请救于秦。", detail: { background: "黄棘之会，齐以为楚负从约，三国相与谋楚；楚方新败，兵食不给。", process: "前303年齐、韩、魏三国共伐楚，楚不能距，使太子横入质于秦而请救；秦出兵而南，三国乃引去。", impact: "秦之救楚非亲楚，取其质而市其地；楚自此内失太子、外失齐、韩，怀王入秦之祸即成于此局。", figures: ["楚怀王","太子横"], place: "楚之淮北与南阳（今皖北、豫西南）", state: "楚、齐、韩、魏", sources: ["《史记·楚世家》","《史记·六国年表》","《战国策·楚策》"], tags: ["伐楚","质子","战国外交"] }, related: ["cn--b304--p01", "cn--b303--f01"] },
  { id: "cn--b303--f01", track: "cn", year: -303, yearApprox: true, dim: "figure", weight: 2, title: "屈原既疏而放江南", summary: "谏怀王毋入秦，既疏绌，遂迁于外。", detail: { background: "屈原名平，为怀王左徒，博闻强志，明于治乱，娴于辞令；同列者争宠而害其能，谗人间之。", process: "怀王末年，屈原既疏不复见，谏王无入秦而不听；其后复被谗而迁于江南。其放逐之年次诸家推定不一，故此处约略系于怀王之末。", impact: "其忧愁幽思而作《离骚》，「其文约，其辞微，其志洁，其行廉」；楚辞之一体由是而尊，南方之文遂别于中原。", figures: ["屈原","楚怀王"], place: "楚郢都与江南（今湖北江陵、洞庭以南）", state: "楚国", sources: ["《史记·屈原贾生列传》","《楚辞·离骚》","王逸《楚辞章句》","钱穆《先秦诸子系年》"], tags: ["屈原","楚辞","放逐"] }, related: ["cn--b312--m01", "cn--b313--p01"] },
  { id: "cn--b301--m01", track: "cn", year: -301, yearApprox: false, dim: "military", weight: 4, title: "垂沙之役，楚师大败", summary: "齐韩魏之师破楚于垂沙，唐昧死之。", detail: { background: "三国以楚合秦而兴兵，楚将唐昧（一作唐蔑）御之于沤水之旁，两军相持而军志不一。", process: "前301年齐、韩、魏与秦合势，大败楚师于垂沙（今河南唐河一带），将军唐昧死之；齐将帅之名诸书不一，说者以匡章为称，故不取一说。楚自横以北至孟诸之地，三国并有其利。", impact: "楚之锐卒再丧，淮北之扰不息，内则有庄蹻之众；《吕氏春秋》书此役诘朝合战，说者以为权分而致败。", figures: ["唐昧","楚怀王"], place: "楚垂沙（今河南唐河境）", state: "楚、齐、韩、魏", sources: ["《史记·楚世家》","《史记·田敬仲完世家》","《吕氏春秋·处方》","《战国策·楚策》"], tags: ["垂沙","楚国","战国战争"] }, related: ["cn--b303--p01", "cn--b300--i01"] },
  { id: "cn--b300--i01", track: "cn", year: -300, yearApprox: true, dim: "institution", weight: 3, title: "魏冉任相与封君之制", summary: "穰侯以外戚为相，封邑食租税之制益重。", detail: { background: "昭王初立，军权与相位并归于魏冉；秦之封君食邑自商鞅以来已有成法。", process: "前300年前后魏冉任秦相，封于穰，益封于陶；其出则将兵攻城，入则临朝，陶之租入与商贾之利并为其奉邑之资。", impact: "封君食邑之重至有「四贵拟于王室」之讥，客卿与外戚并峙之局遂成；后范雎所以专论秦之有太后、穰侯也。", figures: ["魏冉","秦昭王"], place: "秦之穰、陶（今河南邓州、山东定陶）", state: "秦国", sources: ["《史记·穰侯列传》","《史记·秦本纪》","《史记·范雎蔡泽列传》"], tags: ["封君","食邑","外戚"] }, related: ["cn--b306--p01", "cn--b266--p01"] },
  { id: "cn--b298--f01", track: "cn", year: -298, yearApprox: true, dim: "figure", weight: 3, title: "孟尝君入秦而脱", summary: "齐孟尝君相秦岁余，以狗盗、鸡鸣得出关。", detail: { background: "孟尝君田文以薛公子入秦，秦昭王以为相，其后或欲以为质。", process: "约前299—前298年孟尝君在秦，秦欲留之。文使人谢昭王夫人，取所献狐白裘以解；至函谷关，关法「鸡鸣而出客」，客有能为狗盗者，客有能为鸡鸣者，遂先鸡鸣而得出。归薛而秦追骑至。", impact: "《史记》所载多采客所记，「鸡鸣狗盗」之语由此入后世之文；孟尝君归齐任相，齐之复合五国以攻秦。", figures: ["孟尝君","秦昭王","冯谖"], place: "秦函谷关、齐薛（今河南灵宝、山东滕州）", state: "齐、薛、秦", sources: ["《史记·孟尝君列传》","《战国策·秦策四》","《史记·六国年表》"], tags: ["孟尝君","函谷关","门客"] }, related: ["cn--b299--p01", "cn--b296--p01"] },
  { id: "cn--b296--p01", track: "cn", year: -296, yearApprox: false, dim: "politics", weight: 3, title: "楚怀王卒于秦，丧归于楚", summary: "怀王羁留不得归，前296年卒，秦送丧于楚。", detail: { background: "前299年怀王入秦被留，楚人乃于前298年立太子横，是为顷襄王，并告秦；秦怒而出武关伐楚，楚遂不复西。", process: "前296年（顷襄王三年）楚怀王卒于秦，秦送其丧归葬。《楚世家》载「楚人皆怜之，如悲亲戚」，诸侯由是不直秦。", impact: "楚之与秦自怀王之劫遂为世仇，其后合从救邯郸、项氏起兵皆借亡秦为号；屈原之作亦成于此怨愤之世。", figures: ["楚怀王","楚顷襄王","秦昭王"], place: "秦咸阳、楚郢（今陕西咸阳、湖北荆州）", state: "楚、秦", sources: ["《史记·楚世家》","《史记·屈原贾生列传》","《史记·六国年表》（顷襄王元年、三年）"], tags: ["楚怀王之死","顷襄王","秦楚"] }, related: ["cn--b299--p01", "cn--b278--m01"] },
  { id: "cn--b295--p01", track: "cn", year: -295, yearApprox: false, dim: "politics", weight: 4, title: "沙丘之变，主父饿死", summary: "公子章作乱，李兑围主父于沙丘宫三月。", detail: { background: "赵武灵王传国于子何（惠文王），自号主父；欲分赵为二，使安阳君成为代王，而李兑与公子章之党相图。", process: "前295年（赵惠文王四年）主父与王何同游沙丘（今河北广宗西北），公子章与党徒作乱，杀相肥义；李兑之兵已至，公子章败死。李兑遂围主父于沙丘宫，「三月余而杀主父（饿死）」，赵人以重诺相泄。", impact: "赵之霸图随武灵王而终，其后赵以廉颇、赵奢、李牧守其北边与西境；「主父」之祸遂为战国权臣之炯戒。", figures: ["赵武灵王","李兑","肥义","公子章","赵惠文王"], place: "赵沙丘宫（今河北广宗西北）", state: "赵国", sources: ["《史记·赵世家》","《史记·廉颇蔺相如列传》","《资治通鉴》卷五"], tags: ["沙丘之变","赵国","主父"] }, related: ["cn--b307--m02", "cn--b293--m01"] },
  { id: "cn--b293--m01", track: "cn", year: -293, yearApprox: false, dim: "military", weight: 4, title: "伊阙之战，白起破韩魏", summary: "白起以少击众，斩首二十四万，虏公孙喜。", detail: { background: "韩、魏约赵共西向以难秦，魏以公孙喜（犀武）为主将，屯于伊阙（今河南洛阳南，两山相对，伊水中流）。", process: "前293年秦使左更白起攻之于伊阙。韩、魏各欲以他国当秦锋，故言战而实不肯先；白起以疑兵牵韩，而以精锐夜出而薄魏师，魏师既败，韩军不能自立，遂大破之，斩首二十四万，虏公孙喜，拔五城。白起之斩首二十四万，《秦本纪》、《白起列传》、《年表》所记略异，后世考订疑其过当，各方记载差异较大。", impact: "三晋之锐尽于伊阙，韩、魏自此不复能当秦；白起以是大良造，秦之「东郡」「河内」之谋自此益锐。", figures: ["白起","公孙喜","魏昭王","韩釐王","秦昭王"], place: "韩、魏伊阙（今河南洛阳南）", state: "秦、韩、魏", sources: ["《史记·秦本纪》","《史记·白起王翦列传》","《史记·穰侯列传》","梁玉绳《史记志疑》"], tags: ["伊阙","白起","战国战役"] }, related: ["cn--b295--p01", "cn--b288--p01"] },
  { id: "cn--b291--m01", track: "cn", year: -291, yearApprox: true, dim: "military", weight: 3, title: "左更错伐魏取轵", summary: "秦取轵与河内诸城，魏之河内遂蹙。", detail: { background: "魏自徙都大梁之后，河内诸城悬在西方，与绛、安邑之旧地声援不属。", process: "前291年（秦昭王十六年）左更错伐魏，取轵及河内诸城，多所降拔；《秦本纪》所书城数与降人之数与他本不齐，故不取一定之数。", impact: "河内之地入于秦，韩、魏之道为之中断；明年魏尽委河东，即迫于此役。", figures: ["秦昭王","魏冉","魏昭王"], place: "魏之河内轵地（今河南济源东南）", state: "秦、魏", sources: ["《史记·秦本纪》","《史记·魏世家》","《史记·六国年表》"], tags: ["河内","攻取","战国战争"] }, related: ["cn--b293--m01", "cn--b290--p01"] },
  { id: "cn--b290--p01", track: "cn", year: -290, yearApprox: true, dim: "politics", weight: 3, title: "魏委河东，韩纳南阳", summary: "二国以地赂秦求和，河东、南阳入秦。", detail: { background: "伊阙新败、轵道又继之，魏、韩无以拒秦，乃以地易一日之安。", process: "前290年魏尽委河东之地于秦，韩也入若及南阳以请和；所献地方数，史文多寡不齐，说者疑其夸，今两存其说。", impact: "秦有河东则东出之门益宽，三晋之不可复合自此始；魏、韩之邑遂在秦郡县之间。", figures: ["魏昭王","韩釐王","秦昭王"], place: "魏之河东与韩之南阳（今晋南、豫西南）", state: "秦、魏、韩", sources: ["《史记·魏世家》","《史记·韩世家》","《史记·秦本纪》","杨宽《战国史》"], tags: ["赂秦","河东","领土变更"] }, related: ["cn--b291--m01", "cn--b288--p01"] },
  { id: "cn--b289--c01", track: "cn", year: -289, yearApprox: true, dim: "culture", weight: 2, title: "孟子卒，书七篇", summary: "退与万章之徒序诗书，著《孟子》。", detail: { background: "孟子游齐、梁不遇，「焉见王之一言而合」之说既穷，乃归邹。", process: "其晚年「退而与万章之徒序《诗》、《书》，述仲尼之意，作《孟子》七篇」（《史记·孟子荀卿列传》）；卒岁通行推为前289年，亦有前305年、前288年诸说，故系年从约。", impact: "性善、养气、仁政与民贵君轻之论由其书以传；后世言道统者以轲为子思之嗣，齐梁之俗儒遂与之并著。", figures: ["孟轲","万章","公孙丑"], place: "邹（今山东邹城）", state: "邹国", sources: ["《史记·孟子荀卿列传》","《孟子·尽心下》","赵岐《孟子题辞》","焦循《孟子正义》"], tags: ["孟子","儒家","著述"] }, related: ["cn--b349--c01", "cn--b349--c02"] },
  { id: "cn--b288--p01", track: "cn", year: -288, yearApprox: false, dim: "politics", weight: 4, title: "秦称西帝，齐称东帝", summary: "昭王自号西帝，约齐并为东帝。", detail: { background: "穰侯欲广陶封而东伐赵，秦以是结齐；齐新得宋，亦有并天下之心。", process: "前288年十月秦昭王自言西帝，使魏冉持书于齐，请齐王并号为东帝，约共伐赵而分其地；齐王既受而寻去帝号，复称王如故。帛书《战国纵横家书》所录苏秦之辞与此局相涉，而《史记》所次年月与之不合，故两说并存。", impact: "二帝之号旋立旋废，秦以帝市齐之谋不成；齐因得志于宋，诸侯之怨遂移于齐。", figures: ["秦昭王","齐湣王","魏冉","苏秦"], place: "秦咸阳、齐临淄（今陕西咸阳、山东淄博）", state: "秦、齐", sources: ["《史记·秦本纪》","《史记·田敬仲完世家》","《战国策·齐策》","马王堆帛书《战国纵横家书》"], tags: ["帝号","连横","东西二帝"] }, related: ["cn--b286--p01", "cn--b290--p01"] },
  { id: "cn--b288--e01", track: "cn", year: -288, yearApprox: true, dim: "economy", weight: 2, title: "陶之贾与穰侯封邑", summary: "封于陶者兼关市之利，商贾渊薮归侯门。", detail: { background: "陶在济、泗之间，《史记·货殖列传》以为「天下之中」，商贾并凑而其利最厚。", process: "前288年前后穰侯魏冉益封于陶，封邑之租入与关市之征并归其门；说者以范雎后所云「陶在东方」之非秦有，即谓此邑之利。", impact: "封君兼有大市之饶，其富拟于公室，秦之封君与客卿之争由是而著；陶后入王有而置郡。", figures: ["魏冉","秦昭王"], place: "陶（今山东定陶）", state: "秦国", sources: ["《史记·货殖列传》","《史记·穰侯列传》","《史记·范雎蔡泽列传》"], tags: ["定陶","关市","封君"] }, related: ["cn--b300--i01", "cn--b288--p01"] },
  { id: "cn--b286--p01", track: "cn", year: -286, yearApprox: true, dim: "politics", weight: 4, title: "齐灭宋，偃死于温", summary: "齐与楚魏共伐宋，宋遂亡而分其地。", detail: { background: "宋王偃灭滕、伐薛、击楚淮北，诸侯谓之「桀宋」；齐久蓄图宋之计。", process: "前286年齐与楚、魏共伐宋，三国之兵入其国，杀宋王偃于温而宋遂亡，三国分其地；灭宋之岁在湣王末，说者于齐之纪年多异，故系年从约。", impact: "齐并宋之沃野而益骄，燕昭王以是合诸侯之谋；前284年五国之兵即缘宋亡而起。", figures: ["齐湣王","宋王偃","乐毅"], place: "宋之睢阳、定陶与沛地（今河南商丘、山东定陶）", state: "齐、宋", sources: ["《史记·宋微子世家》","《史记·田敬仲完世家》","《战国策·宋策》","《史记·六国年表》"], tags: ["齐灭宋","宋王偃","战国兼并与"] }, related: ["cn--b284--m01", "cn--b288--p01"] },
  { id: "cn--b285--f01", track: "cn", year: -285, yearApprox: true, dim: "figure", weight: 3, title: "苏秦死于齐", summary: "齐大夫争宠使人刺之，车裂以徇于市。", detail: { background: "《史记》称苏秦约从六国、并相六印；帛书所录则其行事多在燕、齐之间。", process: "前285年前后齐大夫有与其争宠者，使人刺苏秦，不死，求贼不得，乃车裂苏秦以徇于市（《史记·苏秦列传》）。马王堆帛书《战国纵横家书》载其与燕昭王、齐湣王往复之书，事在前288至前284际，与《史记》次第不合，故其卒岁不可深泥。", impact: "纵横家之言多夸而书籍散缺，合从之事与为间之事混为一传；帛书出而其年世之别始有端绪。", figures: ["苏秦","齐湣王","燕昭王"], place: "齐都临淄（今山东淄博临淄）", state: "齐、燕", sources: ["《史记·苏秦列传》","《战国策·齐策》","马王堆帛书《战国纵横家书》","钱穆《先秦诸子系年》"], tags: ["合纵","纵横家","苏秦"] }, related: ["cn--b337--c01", "cn--b284--p01"] },
  { id: "cn--b284--m01", track: "cn", year: -284, yearApprox: false, dim: "military", weight: 5, title: "乐毅将五国之兵破齐", summary: "济西一战齐师败散，燕独深入临淄。", detail: { background: "燕昭王卑身厚币以招贤者，以齐前314年破燕之怨为心腹之谋；乐毅自赵往见，辞为亚卿。", process: "前284年燕与秦、楚、三晋合谋，以乐毅为上将军并五国之兵伐齐（从约国名诸书所列不齐，说者有四国、五国之异），与齐战于济西，齐师败走，湣王出亡；乐毅辞还诸侯之师而独将燕军逐北，遂入临淄，尽取其宝器，齐之七十余城皆属燕。", impact: "齐之不服者唯莒与即墨二城，宗庙几绝；齐之富强一役而尽，山东之势由东西并强转为秦独强。", figures: ["乐毅","齐湣王","燕昭王","田单"], place: "齐济西、临淄（今山东聊城以西、淄博临淄）", state: "燕、齐", sources: ["《史记·乐毅列传》","《史记·田敬仲完世家》","《史记·田单列传》","《战国策·燕策》"], tags: ["济西","五国伐齐","乐毅"] }, related: ["cn--b286--p01", "cn--b284--p01"] },
  { id: "cn--b284--p01", track: "cn", year: -284, yearApprox: true, dim: "politics", weight: 4, title: "齐湣王死于莒", summary: "王出亡不受于卫鲁，淖齿杀之于莒。", detail: { background: "济西既败，湣王弃临淄东走，所过之国以其骄而不纳。", process: "前284年湣王出亡，至卫、至鲁、至邹皆不以礼，乃奔莒；楚使淖齿救齐，因与燕分齐，遂杀湣王于莒。《史记》所书死状出于策士之传闻，齐人其后求其尸不得，立太子于莒。", impact: "齐以一国之君死于外救之口，社稷几绝；莒、即墨之守与复国之谋，即起于湣王既死之后。", figures: ["齐湣王","淖齿","乐毅"], place: "莒（今山东莒县）", state: "齐、楚", sources: ["《史记·田敬仲完世家》","《史记·乐毅列传》","《战国策·齐策》","《史记·六国年表》"], tags: ["齐湣王","莒","战国政变"] }, related: ["cn--b284--m01", "cn--b283--p01"] },
  { id: "cn--b283--p01", track: "cn", year: -283, yearApprox: true, dim: "politics", weight: 2, title: "齐立襄王于莒", summary: "法章变姓名灌园，莒人立为襄王。", detail: { background: "湣王死后齐之群臣欲立太子，而淖齿且在莒，齐人惧楚、燕之并。", process: "前283年前后莒中立齐太子法章，是为襄王；其初变姓名从人灌园，太史敫之女见而与私，至是为王后，即后世所称君王后。", impact: "齐之社稷以二城而续，后此田单以即墨破燕军、迎襄王复国者，皆本于襄王既定之名分。", figures: ["齐襄王","法章","君王后"], place: "莒（今山东莒县）", state: "齐国", sources: ["《史记·田敬仲完世家》","《史记·田单列传》","《战国策·齐策》"], tags: ["齐襄王","复国","名分"] }, related: ["cn--b284--p01", "cn--b279--m01"] },
  { id: "cn--b280--m01", track: "cn", year: -280, yearApprox: true, dim: "military", weight: 3, title: "秦越空桑拔黔中", summary: "司马错率陇西之兵由巴道取楚黔中。", detail: { background: "楚自垂沙、丹阳再败，江北之地日蹙；秦得巴蜀，欲由南方绕楚之背。", process: "前280年秦使司马错率陇西之兵，由巴蜀之边径（史称空桑之道）伐楚，拔黔中郡；楚献汉北及上庸之地以求和。其行军之道里与年代，史文简而说者有异。", impact: "秦自巴、蜀临楚之上游，楚之巫、黔中不守，郢都之东遂无所蔽；前278年白起之拔郢即循此势。", figures: ["司马错","楚顷襄王","秦昭王"], place: "楚黔中（今湖南西部、重庆东南）", state: "秦、楚", sources: ["《史记·秦本纪》","《史记·楚世家》","《华阳国志·蜀志》","杨宽《战国史》"], tags: ["黔中","空桑之道","楚衰"] }, related: ["cn--b280--x01", "cn--b278--m01"] },
  { id: "cn--b280--x01", track: "cn", year: -280, yearApprox: true, dim: "explore", weight: 2, title: "巴涪之道与楚西边", summary: "石牛、空桑诸道既通，秦蜀之军得临巫、黔。",detail: { background: "蜀道之险在褒斜、金牛之间，秦取巴蜀后始营栈道以运粮；楚之巫、黔则以水陆相错。", process: "前280年前后秦军连巴、涪之水道与陇西之陆路以出楚之西垂，所谓空桑之道、石牛之栈道皆见于后出之记载，其实则累世渐通者，其始末与道里不可一概而得。", impact: "自是秦、楚相争之场移于江水之上游，江南、巴蜀之粟与竹木得北输；论蜀道之早通者每引此事。", figures: ["司马错"], place: "巴蜀与楚之巫黔（今重庆、鄂西、湘西）", state: "秦、楚", sources: ["《史记·秦本纪》","《华阳国志·蜀志》","《读史方舆纪要》","顾颉刚编《古史辨》论巴蜀地理诸说"], tags: ["蜀道","栈道","地理交通"] }, related: ["cn--b280--m01", "cn--b316--i01"] },
  { id: "cn--b279--p01", track: "cn", year: -279, yearApprox: false, dim: "politics", weight: 3, title: "秦赵会于渑池", summary: "两王为好会，各以酒相献，两无所失。", detail: { background: "秦自拔郢之后欲东向，而赵有廉颇、蔺相如，未可猝图，乃为先好之会。", process: "前279年（赵惠文王二十年）秦昭王与赵王遇于西河之外的渑池（今河南渑池），赵之从臣有蔺相如，廉颇送境而约「王行过三十日不至，则立太子」；会上秦、赵各以献酒、击缶之事相折，两无所失。", impact: "渑池之会成为赵之外交支点，其后长平之役秦先绝赵之援，亦以是会之好为可负；赵之内政自此倚重将相。", figures: ["赵惠文王","秦昭王","蔺相如","廉颇"], place: "渑池（今河南渑池西）", state: "秦、赵", sources: ["《史记·廉颇蔺相如列传》","《史记·赵世家》","《史记·六国年表》"], tags: ["渑池之会","外交","赵国外交"] }, related: ["cn--b279--i01", "cn--b273--m01"] },
  { id: "cn--b279--i01", track: "cn", year: -279, yearApprox: true, dim: "institution", weight: 2, title: "赵之将相分职", summary: "相如让颇以先国家之急，卒为刎颈之交。", detail: { background: "蔺相如以奉使与会上折秦之功拜为上卿，位在故将廉颇之右，颇耻为之下，扬言欲面辱之。", process: "前279年前后相如每朝常称病，出则引车避匿，曰「以先国家之急而后私仇」；颇闻之，肉袒负荆因宾客至相如门谢罪，遂相与欢，为刎颈之交（《史记·廉颇蔺相如列传》）。", impact: "将、相分职而以国事相让，为战国之赵所以能当其西北兵冲者之一端；后世言文武之任相须，每引此事。", figures: ["蔺相如","廉颇"], place: "赵都邯郸（今河北邯郸）", state: "赵国", sources: ["《史记·廉颇蔺相如列传》","《战国策·赵策》","钱穆《先秦诸子系年》"], tags: ["将相和","官制","赵国"] }, related: ["cn--b279--p01", "cn--b262--p01"] },
  { id: "cn--b279--m01", track: "cn", year: -279, yearApprox: true, dim: "military", weight: 5, title: "田单以火牛破燕", summary: "即墨纵火牛，燕军走，齐城尽叛燕。", detail: { background: "燕惠王即位，以骑劫代乐毅，齐之即墨唯田单守之；单乃纵反间，又令老弱乘城、以私钱馈燕将，示以怯。", process: "前279年前后田单收城中得千余牛，为绛缯衣、画以五彩龙文，束兵刃于其角而灌脂束苇于尾，凿城数十穴，夜纵牛，壮士五千人随其后；牛尾热而怒奔燕军，燕军大乱，走，杀骑劫。齐之所属城皆言叛燕，接轸至临淄，乃迎襄王于莒而入居。", impact: "以二城而复七十余城之齐，战国守城用奇之最著者；然齐自是亦不复争天下，君臣相疑，遂至终秦之世不入于难。", figures: ["田单","骑劫","齐襄王","燕惠王"], place: "齐即墨（今山东平度东南）", state: "齐、燕", sources: ["《史记·田单列传》","《史记·乐毅列传》","《战国策·齐策》","杨宽《战国史》"], tags: ["即墨","火牛","守城"] }, related: ["cn--b284--m01", "cn--b279--f01"] },
  { id: "cn--b279--f01", track: "cn", year: -279, yearApprox: true, dim: "figure", weight: 2, title: "乐毅奔赵，封望诸君", summary: "代将以骑劫，毅遂奔赵，赵封于观津。", detail: { background: "燕惠王以骑劫代乐毅，毅知不免，西奔赵；赵、燕皆欲得其用。", process: "前279年前后乐毅去燕奔赵，赵封之于观津，号望诸君；燕惠王悔而让之，毅报书，其辞以「古之君子，交绝不出恶声；忠臣去国，不洁其名」为言（《史记·乐毅列传》）。", impact: "一将之去留系两国之强弱，燕、齐之局由是而定；其报书遂为战国书牍之传，后世以为士之立节者取则焉。", figures: ["乐毅","燕惠王","赵惠文王"], place: "赵之观津（今河北武邑东）", state: "燕、赵", sources: ["《史记·乐毅列传》","《史记·廉颇蔺相如列传》","《战国策·燕策》"], tags: ["乐毅","奔亡","书牍"] }, related: ["cn--b284--m01", "cn--b279--m01"] },
  { id: "cn--b278--m01", track: "cn", year: -278, yearApprox: false, dim: "military", weight: 5, title: "白起拔郢，烧夷陵", summary: "秦克楚都，焚先王之墓，楚东走于陈。", detail: { background: "楚自垂沙、丹阳、黔中屡败，郢都之备不修；秦军由汉水下，楚之民众去其坟墓而恋。", process: "前278年秦使武安君白起伐楚，拔郢（今湖北荆州北），烧夷陵（楚之先王墓所），东至竟陵；楚顷襄王东北走，度城不守，乃东徙于陈。秦以其地为南郡，而江南、巫黔相继入秦。", impact: "楚失其根本之与先王之墟，自是为秦之东方诸侯而非抗秦之主；秦之东向自此少一劲敌，齐、赵之势愈孤。", figures: ["白起","楚顷襄王","秦昭王"], place: "楚郢、夷陵、陈（今湖北荆州、枝江、河南淮阳）", state: "秦、楚", sources: ["《史记·白起王翦列传》","《史记·楚世家》","《史记·秦本纪》","《读史方舆纪要》"], tags: ["郢都","白起","南郡"] }, related: ["cn--b278--f01", "cn--b280--m01"] },
  { id: "cn--b278--f01", track: "cn", year: -278, yearApprox: true, dim: "figure", weight: 3, title: "屈原自沉汨罗", summary: "作《怀沙》之赋，于是遂赴湘流。", detail: { background: "郢之既亡，屈原以放逐之身在江南，「被发行吟泽畔，颜色憔悴」。", process: "前278年前后（其生卒与死岁本无明文，此从通行之说）屈原作《怀沙》，乃赴汨罗以死；其《九歌》《离骚》之属，说者或谓作于放后，或谓在怀王之世，二说并存。", impact: "《楚辞》之一体由屈原而立其名，后世以《离骚》与《诗》并称；其死缘宗国沦亡，太史公读其书而悲其志。", figures: ["屈原","楚顷襄王"], place: "楚之汨罗（今湖南汨罗江流域）", state: "楚国", sources: ["《史记·屈原贾生列传》","《楚辞·九章·怀沙》","王逸《楚辞章句》","游国恩《楚辞论文集》"], tags: ["屈原","楚辞","汨罗"] }, related: ["cn--b303--f01", "cn--b278--m01"] },
  { id: "cn--b278--p01", track: "cn", year: -278, yearApprox: true, dim: "politics", weight: 3, title: "楚徙都于陈", summary: "郢既陷，顷襄王东北渡河，保陈而连齐。", detail: { background: "楚之旧都以江、汉之间为本根，宗庙、坟墓在焉。", process: "前278年郢亡之后楚王保于陈（今河南淮阳），因陈之与齐、魏相近，乃东连齐而西备秦；其地非楚之旧，故令、尹之势渐移于东方之邑。", impact: "楚之中枢自此东移，陈与后此之寿春皆非其根本之地；论楚之所以不能复振者，每原于徙都之失。", figures: ["楚顷襄王","春申君"], place: "陈（今河南淮阳）", state: "楚国", sources: ["《史记·楚世家》","《史记·春申君列传》","《史记·六国年表》"], tags: ["徙都","楚国","陈"] }, related: ["cn--b278--m01", "cn--b276--p01"] },
  { id: "cn--b277--x01", track: "cn", year: -277, yearApprox: true, dim: "explore", weight: 3, title: "庄蹻循江略滇", summary: "楚军至滇池，会秦取黔中而道塞王焉。", detail: { background: "楚欲西南通巴黔之外，循江以上有三千余里之水道可略地。", process: "前277年前后（一说在楚威王之世，两说并存）楚使将军庄蹻循江上，略巴、黔中以西，至滇池（今云南昆明一带）而王其地；会秦拔楚之巴、黔中，道塞不复得归。", impact: "中原之兵与器南入滇池，楚人之众遂变其服俗以长之；论西南夷与楚交通之始者以是为最早之纪事。", figures: ["庄蹻","楚顷襄王"], place: "楚之巴黔与滇池（今川东南、黔西、云南昆明）", state: "楚", sources: ["《史记·西南夷列传》","《华阳国志·南中志》","《史记·楚世家》","杨宽《战国史》"], tags: ["滇池","西南夷","水道交通"] }, related: ["cn--b280--x01", "cn--b316--p01"] },
  { id: "cn--b276--p01", track: "cn", year: -276, yearApprox: true, dim: "politics", weight: 2, title: "楚收东地之兵", summary: "亡郢之后东收邑兵，谋复陈以东之地。", detail: { background: "郢既陷，秦以郡县其地，楚之故邑东移者尚多有兵。", process: "前276年顷襄王收东地之邑兵而北谋秦，所得城邑与兵数史文不详，说者以其众号十余万为夸大之辞，故不取其数；秦复东拔之，楚遂不得所欲。", impact: "楚之复取旧地不成，而江南之民尽入于秦；此后楚之图秦惟在合纵一途，春申君之任由此而起。", figures: ["楚顷襄王","春申君","秦昭王"], place: "楚之东地（今河南东南、安徽北部）", state: "楚、秦", sources: ["《史记·楚世家》","《史记·春申君列传》","《史记·六国年表》"], tags: ["楚国","复国","东地"] }, related: ["cn--b278--p01", "cn--b263--p01"] },
  { id: "cn--b274--c01", track: "cn", year: -274, yearApprox: true, dim: "culture", weight: 3, title: "荀卿游齐，三为祭酒", summary: "赵人荀况入稷下，三为祭酒而去齐。", detail: { background: "齐之稷下自威、宣以来致天下之士，至襄王而学士稍衰。", process: "前274年前后荀况至齐讲学，「三为祭酒」（《史记·孟子荀卿列传》）；其年「五十始游齐」之文，说者或以为当作十五，二说并存。以襄王不足与有为之君，乃去齐而之楚。", impact: "性恶、化性起伪与《天论》《礼论》之说由稷下之辩而出，其门人韩非、李斯入秦；齐之学术正统由此北散。", figures: ["荀况","齐襄王"], place: "齐都临淄稷下（今山东淄博临淄）", state: "齐、赵", sources: ["《史记·孟子荀卿列传》","《荀子·天论》","刘向《荀子叙录》","钱穆《先秦诸子系年》"], tags: ["稷下学宫","荀子","性恶"] }, related: ["cn--b349--c01", "cn--b274--a01"] },
  { id: "cn--b274--a01", track: "cn", year: -274, yearApprox: true, dim: "art", weight: 2, title: "长沙楚墓之帛画与漆绘", summary: "人物龙凤之帛画，与漆棺彩绘同出于楚墓。", detail: { background: "楚之绘画在缯帛与漆器，江南之墓多存其物，其时属战国中期至晚期。", process: "前274年前后（依墓型与器物推定，非纪年明文）长沙一带楚墓所出人物龙凤帛画与人物御龙帛画，绘于缯帛，以为丧仪之属；同出者有漆棺之彩绘、木俑与丝麻之衣。", impact: "帛画为今见最早的独立绘画之例，楚人之图写与中原之器饰判为二体；论中国绘画之源者恒取是物。", figures: ["楚之工师"], place: "长沙之楚墓（今湖南长沙）", state: "楚国", sources: ["《长沙楚墓》（《考古学报》1962年第1期）","《楚辞·招魂》","沈从文《中国古代服饰研究》"], tags: ["帛画","楚文化","漆器"] }, related: ["cn--b274--c01", "cn--b278--f01"] },
  { id: "cn--b273--m01", track: "cn", year: -273, yearApprox: true, dim: "military", weight: 4, title: "华阳之役，白起救韩", summary: "秦败魏、赵之师于华阳，魏割八城以和。", detail: { background: "魏、赵共攻韩之雍氏，韩告急于秦；秦远在南阳之师道阻。", process: "前273年秦使白起、胡伤救韩，趋华阳（今河南新郑北）而下之，大破魏、赵之师；《史记》所书斩首与沉河之数各篇不齐，说者疑其过实，故不取一定之数。魏乃割八城以和，赵之援亦止。", impact: "秦越韩、魏之境而败二国之众于其腹心，所谓远交近攻之形已见；韩自此为秦之东间，赵、魏不复能合。", figures: ["白起","魏安釐王","韩釐王","赵惠文王"], place: "韩之华阳（今河南新郑北）", state: "秦、韩、魏、赵", sources: ["《史记·白起王翦列传》","《史记·魏世家》","《史记·韩世家》","《史记·赵世家》"], tags: ["华阳","救韩","战国战争"] }, related: ["cn--b272--i01", "cn--b266--p01"] },
  { id: "cn--b272--i01", track: "cn", year: -272, yearApprox: true, dim: "institution", weight: 4, title: "秦灭义渠，置陇西、北地郡", summary: "义渠之众散，秦始置边郡而筑长城距胡。", detail: { background: "义渠杂错于泾、洛之间，历代为秦西垂之患；宣太后与义渠君有旧，诱而杀之。", process: "前272年前后（《匈奴列传》《秦本纪》《后汉书·西羌传》系年互异，故从约）秦乘义渠内乱伐而灭之，置陇西、北地、上郡，因边地筑长城以距胡；其治所与郡界后出者不同。", impact: "秦无西顾之忧，得专意东向与南取楚地；陇西、北地之开为后此取河西、蜀道转运之本。", figures: ["秦昭王","宣太后","魏冉"], place: "秦之陇西、北地（今甘肃东南、宁夏南部）", state: "秦国", sources: ["《史记·匈奴列传》","《史记·秦本纪》","《后汉书·西羌传》","顾祖禹《读史方舆纪要》"], tags: ["义渠","边郡","长城"] }, related: ["cn--b306--m01", "cn--b273--m01"] },
  { id: "cn--b270--m01", track: "cn", year: -270, yearApprox: true, dim: "military", weight: 3, title: "秦围赵阏与", summary: "秦出上党围阏与，赵诸将以道远隘不救。", detail: { background: "华阳既败，韩、魏俱敝，秦乃移兵北向，图上党之险。", process: "前270年前后秦军围赵之阏与（今山西和顺西北），赵王以问诸将，廉颇、乐乘与蔺相如皆以道远险狭为不可救；赵奢独谓两鼠斗于穴中，勇者胜。", impact: "一城之存关系赵之东阳与上党，赵卒用赵奢之议，秦不得遽东；战国山城之守自此为世所重。", figures: ["赵奢","廉颇","蔺相如","秦昭王","赵惠文王"], place: "赵阏与（今山西和顺西北）", state: "秦、赵", sources: ["《史记·廉颇蔺相如列传》","《史记·赵世家》","《史记·六国年表》"], tags: ["阏与","围城","赵国"] }, related: ["cn--b269--m01", "cn--b273--m01"] },
  { id: "cn--b269--m01", track: "cn", year: -269, yearApprox: true, dim: "military", weight: 4, title: "赵奢破秦于阏与", summary: "卷甲二日而至，据北山，大破秦师。", detail: { background: "赵以赵奢为将将兵救阏与，秦军壁于武安之西，军于阏与与邯郸之间。", process: "前269年前后奢将而东，去邯郸三十里而止，增垒二十八日不出，以误秦之间；既乃卷甲兼行，二日一夜至军前，从许历之计据北山，秦人至，奢纵兵击之，大破秦师，阏与遂解。此役《史记》但书大破之而所杀获之数不著。", impact: "赵赐奢号马服君，与廉颇、蔺相如并重；秦自华阳之后再折于赵，东出之谋为之一缓。", figures: ["赵奢","许历","赵惠文王"], place: "阏与、武安（今山西和顺、河北武安）", state: "赵、秦", sources: ["《史记·廉颇蔺相如列传》","《史记·赵世家》","杨宽《战国史》"], tags: ["阏与","赵奢","救赵"] }, related: ["cn--b270--m01", "cn--b269--i01"] },
  { id: "cn--b269--i01", track: "cn", year: -269, yearApprox: true, dim: "institution", weight: 2, title: "赵奢行赋与封君之家", summary: "平原君家不出租，奢刑其用事者。", detail: { background: "战国行赋以田与户为科，贵近之家多倚其势而不出。", process: "赵奢以田部吏行赋，平原君家不出租，当者九人，奢刑其用事者以徇；平原君怒而欲杀之，奢为言国法削则主位不尊、赵将不固之义，平原君贤之而荐于王。", impact: "吏不敢避贵近，赵以之国富兵强，得与秦相抵数十年；战国课计之行于三晋者，可见于此。", figures: ["赵奢","平原君"], place: "赵都邯郸与平原之邑（今河北邯郸、山东平原一带）", state: "赵国", sources: ["《史记·廉颇蔺相如列传》","《史记·平原君虞卿列传》","《史记·赵世家》"], tags: ["赋税","封君","赵国"] }, related: ["cn--b269--m01", "cn--b309--i01"] },
  { id: "cn--b268--s01", track: "cn", year: -268, yearApprox: true, dim: "science", weight: 2, title: "秦用颛顼历", summary: "以十月为岁首，秦之历日行于其国。", detail: { background: "古之历有黄帝、颛顼、夏、殷、周、鲁之六术，诸侯各行其朔。", process: "战国秦人之历以十月为岁首，色尚赤，数从水德，后世称颛顼历；其行用之始无明文，说者谓在春秋末至战国中世，秦统一后遂颁行焉。", impact: "岁首不同则牺牲、祭祀、政令之月皆异于夏时；汉初仍用秦历，至太初改历始变，其制之广可见。", figures: ["秦昭王"], place: "秦之咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·历书》","《史记·秦始皇本纪》","《汉书·律历志》"], tags: ["颛顼历","历法","岁首"] }, related: ["cn--b240--s01", "cn--b266--p01"] },
  { id: "cn--b266--m01", track: "cn", year: -266, yearApprox: true, dim: "military", weight: 3, title: "远交而近攻", summary: "范雎定先后之序，先取韩之太行河内。", detail: { background: "秦之兵旧越韩、魏而攻齐之刚、寿，得其地而不可守也。", process: "前266年后范雎说昭王以「远交而近攻」，谓得一寸则王之寸、得一尺则王之尺；其序先在韩之南阳与河内，而后以及赵、魏之都，齐、楚远者不必先问。", impact: "韩遂为秦之食道，上党、河内之役相属而起；论秦并六国之次第者以范雎之言为定计。", figures: ["范雎","秦昭王"], place: "秦咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·范雎蔡泽列传》","《战国策·秦策三》","《史记·白起王翦列传》"], tags: ["远交近攻","战略","秦国"] }, related: ["cn--b266--p01", "cn--b264--m01"] },
  { id: "cn--b265--s01", track: "cn", year: -265, yearApprox: true, dim: "science", weight: 3, title: "燕下都之铁兵与淬刃", summary: "刀剑矛镞多用铁，渗碳淬火之法已具。", detail: { background: "兵之质自青铜而转铁，战国中晚期而剑、矛、戟之制大变。", process: "河北易县燕下都遗址所出铁质之刀、剑、矛、戟、甲片与镞，多经渗碳或淬火之处理，其期属战国中晚期至秦初，非一时之物；同时韩之棠溪、墨阳以剑名，见于《史记·苏秦列传》所称。", impact: "卒之利钝判于铁与钢，徒兵之战由是益重；论战国兵器之变革者每取燕下都之出土为据。", figures: ["苏秦"], place: "燕下都武阳（今河北易县东南）", state: "燕、韩", sources: ["河北省文物管理委员会《燕下都遗址发掘简报》","《史记·苏秦列传》","《考工记》（《周礼》补）"], tags: ["铁器","淬火","兵器"] }, related: ["cn--b266--m01", "cn--b264--m01"] },
  { id: "cn--b264--m01", track: "cn", year: -264, yearApprox: true, dim: "military", weight: 3, title: "白起取韩南阳", summary: "绝太行之道，韩之都与上党不相救。", detail: { background: "韩介秦、魏之间，太行以南之地与其国都本以一道相通。", process: "前264年至前263年秦使白起攻韩之南阳，拔缑氏、限堡诸城而绝太行之路；《白起列传》书斩首五万，《六国年表》所记与之不侔，说者疑其过当，今两存其文而不取一数。", impact: "韩之上党与都既不相救，则守令无所禀命；前262年上党之入赵，其根本即在此役。", figures: ["白起","韩桓惠王","范雎"], place: "韩之南阳与太行诸隘（今河南中部、晋东南）", state: "秦、韩", sources: ["《史记·白起王翦列传》","《史记·韩世家》","《史记·秦本纪》","《史记·六国年表》"], tags: ["南阳","太行","战略"] }, related: ["cn--b262--m01", "cn--b266--m01"] },
  { id: "cn--b264--c01", track: "cn", year: -264, yearApprox: true, dim: "culture", weight: 2, title: "《尔雅》释诂之辑", summary: "以类相从之故训汇编，其辑非出一手。", detail: { background: "诸夏之言与楚、越之语殊异，经师之读又各有故训，故释诂之编渐具。", process: "《尔雅》十九篇，释诂、释言、释训而下及亲属、宫室、器物、草木、虫鱼、鸟兽；其始辑与成书之岁并无明文，说者或系之孔子之门，或谓草创于战国之末而增益于汉人，今从后说而约略系之。", impact: "为今存最早之训诂林，后世注经之学与字书之部类皆自是出；名物之考由经师之口转而载于竹帛。", figures: ["郭璞"], place: "齐、鲁与三晋之学官（说者所据各异）", state: "诸夏之学", sources: ["《尔雅》十九篇","《汉书·艺文志》","郭璞《尔雅注》","周祖谟《尔雅校笺》"], tags: ["训诂","经学","字书"] }, related: ["cn--b274--c01", "cn--b268--s01"] },
  { id: "cn--b263--e01", track: "cn", year: -263, yearApprox: true, dim: "economy", weight: 2, title: "卓氏入蜀治铁山", summary: "秦徙豪民实蜀，卓氏求沃饶而擅鼓铸。", detail: { background: "秦于新取之地辄徙民实之，山东之贾人遂多入巴蜀；蜀之临邛有铁山。", process: "前263年前后（其岁史无明文，说者推定）卓氏自赵见徙入蜀，求汶山之下沃饶之邑而居临邛，即山鼓铸、运筹策，富至拟于封君；后此程郑与之并，秦、汉之铁业遂以蜀为称首。", impact: "冶铁之业因徙民而南迁，临邛之盐铁自此甲于蜀中；论私营手工业之起者每举卓氏、程郑为证。", figures: ["卓氏","程郑"], place: "蜀之临邛（今四川邛崃）", state: "秦国", sources: ["《史记·货殖列传》","《汉书·地理志》","《华阳国志·蜀志》"], tags: ["冶铁","临邛","徙民"] }, related: ["cn--b316--i01", "cn--b336--e01"] },
  { id: "cn--b263--p01", track: "cn", year: -263, yearApprox: true, dim: "politics", weight: 2, title: "周与秦会于泾池", summary: "西周、东周之君复见于秦，周祚尽于数邑。", detail: { background: "周之分而为西周、东周也，两君各以数邑当强国之冲。", process: "前263年周之君臣复与秦会于泾池（一说在洛阳附近，地望与年次说者不一），秦之命于是乎行于王畿；赧王且借于富商以从诸侯之谋，故其台后有「逃债」之名。", impact: "天子之号仅存于会盟之文，九鼎之数遂寄于秦人之手；后此九年而周遂不祀。", figures: ["周赧王","秦昭王"], place: "王畿（今河南洛阳一带）", state: "周、秦", sources: ["《史记·周本纪》","《史记·秦本纪》","《史记·六国年表》","《战国策·西周策》"], tags: ["东周西周","名分","九鼎"] }, related: ["cn--b256--p01", "cn--b266--p01"] },
  { id: "cn--b262--m01", track: "cn", year: -262, yearApprox: false, dim: "military", weight: 3, title: "秦拔韩野王", summary: "河内之道既绝，韩之上党成为孤地。", detail: { background: "南阳既陷，秦复东规野王，韩之河内诸城势如隔越。", process: "前262年秦拔韩之野王（今河南沁阳），河内之路遂绝；韩之系于上党者惟太行一道，故韩王恐，使使者请纳上党于秦以缓兵。", impact: "上党之地自此不入于韩而入于赵，长平之役以三郡之民为张本；战国形势之变每系于一城一隘。", figures: ["秦昭王","韩桓惠王"], place: "韩野王（今河南沁阳）", state: "秦、韩", sources: ["《史记·白起王翦列传》","《史记·赵世家》","《史记·韩世家》"], tags: ["野王","上党","长平"] }, related: ["cn--b264--m01", "cn--b262--p01"] },
  { id: "cn--b262--p01", track: "cn", year: -262, yearApprox: false, dim: "politics", weight: 4, title: "上党守降赵", summary: "冯亭以路绝纳其上党于赵，赵受之。", detail: { background: "野王既拔，上党之路绝，其守不能自属于韩，乃谋移其地于赵而嫁其祸。", process: "前262年韩之上党守冯亭使使告赵，请以其邑入于赵；平阳君豹以为此移祸之谋，不可受，平原君胜以为可以得地而无兵，赵王遂使胜往受之。亭之封号与所封邑数诸书互异，说出后世记载，故不取。", impact: "秦怒赵之取其上党，再岁而有长平之役；赵以受降之名而丧其举国精锐，战国言祸福相寻者以此为极。", figures: ["冯亭","赵孝成王","平原君","赵豹"], place: "韩之上党（今山西东南部）", state: "赵、韩、秦", sources: ["《史记·赵世家》","《史记·白起王翦列传》","《史记·平原君虞卿列传》","《史记·六国年表》"], tags: ["上党","冯亭","长平"] }, related: ["cn--b260--m01", "cn--b262--m01"] },
  { id: "cn--b261--m01", track: "cn", year: -261, yearApprox: true, dim: "military", weight: 3, title: "廉颇长平坚壁", summary: "秦攻长平，颇三壁不出，相持岁余。", detail: { background: "赵既受上党，秦乃移新胜之师攻之，赵以廉颇为将，军于长平。", process: "前261年前后秦使将（史作王齮，一作风龛）攻长平，破赵之西城而虏其四尉；颇收余卒而坚壁以待之，使者往来而不敢复战，相持至于岁余，两军之食俱不给。", impact: "长平之相持为战国最久之围战，赵以是请和于秦而诸侯之救益疏；其后代颇者以速进取败，正坐不知此局之难。", figures: ["廉颇","赵孝成王","秦昭王"], place: "赵长平（今山西高平西北）", state: "秦、赵", sources: ["《史记·白起王翦列传》","《史记·廉颇蔺相如列传》","《史记·赵世家》"], tags: ["长平","廉颇","相持"] }, related: ["cn--b262--p01", "cn--b260--m01"] },
  { id: "cn--b260--m01", track: "cn", year: -260, yearApprox: false, dim: "military", weight: 5, title: "长平之役，赵括军败", summary: "赵括出击，白起以奇兵绝其后，括死军降。", detail: { background: "赵王以颇为怯，又中秦之反间，乃以赵括代颇，括至则悉改其约束，为出击之势；蔺相如病而固谏，括母亦上书言其不可。", process: "前260年秦阴使武安君白起为上将军，以诈败诱赵军，而别遣奇兵二万五千人绝赵之后、五千余人胁其壁，分赵军为二；赵卒不得食四十余日而内相杀食，括自出锐卒搏战，秦军射杀之，军遂复降于秦。白起乃杀其降卒，惟遣其年少者二十四人归赵。前后所杀虏，《白起列传》书四十五万，《赵世家》与《年表》作四十万，二说并存而不取一定之数；说者以计吏上功之数多夸，故其详终不可校。", impact: "赵之壮丁尽于一役，邯郸之围即其后果；山东之国股栗，秦并天下之势成而不可反。战国之战以全歼为言者以此为极。", figures: ["白起","赵括","秦昭王","赵孝成王"], place: "赵长平（今山西高平西北）", state: "秦、赵", sources: ["《史记·白起王翦列传》","《史记·赵世家》","《史记·六国年表》","梁玉绳《史记志疑》","杨宽《战国史》"], tags: ["长平","白起","降卒"] }, related: ["cn--b261--m01", "cn--b257--m01"] },
  { id: "cn--b259--m01", track: "cn", year: -259, yearApprox: false, dim: "military", weight: 3, title: "秦三路攻赵", summary: "长平之后分军，取太原之县而围邯郸。", detail: { background: "长平既克，白起欲遂围邯郸以灭赵，秦昭王以应侯之言罢兵而收韩、魏之地。", process: "前259年秋秦复伐赵，分其军为三路：一出上党指邯郸，一取太原之榆次、新城、狼孟等县，一循河东而东；其围邯郸之师将王陵折于城下而却。", impact: "赵之太原属县尽入于秦，河东与上党之路为秦所有；邯郸之围起，秦、赵之胜负遂系于诸侯之救。", figures: ["秦昭王","王陵","白起"], place: "赵之太原、邯郸（今山西太原、河北邯郸）", state: "秦、赵", sources: ["《史记·秦本纪》","《史记·白起王翦列传》","《史记·赵世家》"], tags: ["太原","邯郸之围","分进"] }, related: ["cn--b260--m01", "cn--b258--d01"] },
  { id: "cn--b258--m02", track: "cn", year: -258, yearApprox: true, dim: "military", weight: 2, title: "秦复拔魏邢丘", summary: "河东诸城再陷，魏河内之民徙于秦。", detail: { background: "秦既得韩之上党与河内，复取魏之邢丘以通河上之运。", process: "前258年前后（《秦本纪》作昭王四十九年，《魏世家》年次与之小异）秦拔魏之邢丘（今河南温县东北），其民得徙而秦置吏守之，河内之与邯郸声援由是益通。", impact: "魏之河东尽于邢丘一邑而不可复振，秦得以全力东向邯郸；三晋之相接者惟余太行以东数城。", figures: ["秦昭王","魏安釐王"], place: "魏邢丘（今河南温县东北）", state: "秦、魏", sources: ["《史记·秦本纪》","《史记·魏世家》","《史记·六国年表》"], tags: ["邢丘","河内","攻取"] }, related: ["cn--b259--m01", "cn--b276--p01"] },
  { id: "cn--b258--d01", track: "cn", year: -258, yearApprox: true, dim: "disaster", weight: 3, title: "邯郸围中粮尽", summary: "城守累月，炊骨易子，史不书其数。", detail: { background: "长平之战，赵之壮丁几乎尽矣，城守之众多出老弱与女子。", process: "前258年前后秦军围邯郸，历时逾年而救兵不至；《战国策·赵策》与《史记》于城中「炊骨易子」之状有载，死伤与饿殍之数则史不书其数。", impact: "赵以残弊守一城而支秦之大众，诸侯之救至而围解；围城之酷与养士之用，遂为后世论邯郸之役者两存之两端。", figures: ["赵孝成王","平原君","秦昭王"], place: "赵都邯郸（今河北邯郸）", state: "赵、秦", sources: ["《战国策·赵策三》","《史记·平原君虞卿列传》","《史记·魏公子列传》"], tags: ["邯郸","饥馑","围城"] }, related: ["cn--b259--m01", "cn--b257--m01"] },
  { id: "cn--b258--p01", track: "cn", year: -258, yearApprox: true, dim: "politics", weight: 3, title: "毛遂定从于楚殿", summary: "十九人至楚，日中不决，遂按剑而上。", detail: { background: "邯郸急，平原君求救于楚，欲得门下文武具备者二十人同行，而少其一。", process: "前258年前后毛遂以舍人自赞而预其数，至楚都陈（今河南淮阳）说楚王，日出而言之至日中不决；遂按剑历阶而上，历言楚之地方、众口与合从之利害，楚王乃定从于殿上，遣公子春申君将而救赵。", impact: "以口舌折万乘之君而存赵，战国客卿之效至此而著；楚之救虽缓，然合从之旗由是复竖。", figures: ["毛遂","平原君","楚考烈王","春申君"], place: "楚都陈（今河南淮阳）", state: "楚、赵", sources: ["《史记·平原君虞卿列传》","《史记·楚世家》","《战国策·楚策》"], tags: ["合从","毛遂","公子"] }, related: ["cn--b257--m01", "cn--b251--p01"] },
  { id: "cn--b258--f01", track: "cn", year: -258, yearApprox: true, dim: "figure", weight: 2, title: "鲁仲连义不帝秦", summary: "游邯郸而拒帝秦之议，围解不受封。", detail: { background: "魏使新垣衍在邯郸，主为赵以秦为帝以解围。", process: "前258年前后鲁仲连游赵，闻之，见平原君与新垣衍，为言帝秦之害与三晋之臣不甘其下；衍拜谢不复敢言，《史记》且载秦将闻之为却军五十里。邯郸围解，平原君欲封之，仲连以士之为人在排难解纷而不受谢，遂辞行。", impact: "一布衣之口舌而拒帝号之议，战国处士之气节于此见之；后世言义不帝秦者，皆以此为据而及其辞。", figures: ["鲁仲连","新垣衍","平原君"], place: "赵都邯郸（今河北邯郸）", state: "赵、齐", sources: ["《史记·鲁仲连邹阳列传》","《战国策·赵策三》","《史记·魏公子列传》"], tags: ["鲁仲连","帝秦","处士"] }, related: ["cn--b258--d01", "cn--b257--m01"] },
  { id: "cn--b257--m01", track: "cn", year: -257, yearApprox: false, dim: "military", weight: 5, title: "信陵君矫魏兵而救赵", summary: "夺晋鄙之军，却秦于邯郸城下。", detail: { background: "魏王使将军晋鄙将十万之众救赵，畏秦而壁于邺，使客新垣衍令赵自帝秦。", process: "前257年公子无忌从侯生之计，因如姬得虎符，至邺矫令夺晋鄙之军，使朱亥椎杀鄙之不逞者，勒兵而进；公子身先士卒，楚之春申君与魏之救俱至，秦军数却而解围去。是役也秦失其东出之机，而前此围城诸将之丧败，《史记》于年次人名互有异同，今不取一说。", impact: "邯郸得全而赵不复振，秦自长平以来之锐一挫；山东合从之终举在此年，其后信陵君再合五国而致秦于河外，即本此功。", figures: ["信陵君","朱亥","晋鄙","春申君"], place: "邺、邯郸（今河北临漳、邯郸）", state: "魏、赵、秦", sources: ["《史记·魏公子列传》","《史记·平原君虞卿列传》","《史记·白起王翦列传》","《战国策·赵策》"], tags: ["窃符","邯郸","信陵君"] }, related: ["cn--b257--p01", "cn--b258--d01"] },
  { id: "cn--b257--p01", track: "cn", year: -257, yearApprox: false, dim: "politics", weight: 3, title: "白起赐死于杜邮", summary: "辞行而不肯起，既而复使，遂赐剑。", detail: { background: "秦既罢长平之师，应侯与白起议有先后之异；邯郸之围既败，秦王再欲起之。", process: "前257年白起以疾辞不行，及秦军数却，王让之起，起惧而称病；于是免其官爵，徙之阴密，未行而使人追赐剑，遂自杀于咸阳之杜邮（今陕西咸阳东北）。", impact: "秦之诸将与功臣由是知不受命之祸，而应侯之与白起相倾亦为论者所及；邯郸一役并丧其名将。", figures: ["白起","范雎","秦昭王"], place: "秦之杜邮（今陕西咸阳东北）", state: "秦国", sources: ["《史记·白起王翦列传》","《史记·范雎蔡泽列传》","《史记·秦本纪》"], tags: ["白起","赐死","将相"] }, related: ["cn--b257--m01", "cn--b266--p01"] },
  { id: "cn--b256--p01", track: "cn", year: -256, yearApprox: false, dim: "politics", weight: 5, title: "秦取王畿，九鼎入秦", summary: "西周君举国入秦，赧王崩而周祀遂绝。", detail: { background: "周之君臣与诸侯谋距秦，事泄而秦师至，王畿震恐。", process: "前256年（周赧王五十九年）西周君自归其罪，尽献其地，秦受其籍；《周本纪》著三十六邑与民数之籍，与他记不齐，说者疑其非尽实。是岁赧王崩而周不祀，九鼎之器迁于秦。后世又有一鼎没于泗水之说，出于秦皇渡泗之传闻。", impact: "天子之位至是而空，纪年遂归于秦；鼎与祀之移于咸阳，为后此称帝者立名物之据。", figures: ["周赧王","秦昭王"], place: "周之王畿与河南（今河南洛阳至陕县一带）", state: "周、秦", sources: ["《史记·周本纪》","《史记·秦本纪》","《史记·封禅书》","《史记·六国年表》"], tags: ["九鼎","灭周","名分"] }, related: ["cn--b263--p01", "cn--b249--p02"] },
  { id: "cn--b256--s03", track: "cn", year: -256, yearApprox: true, dim: "science", weight: 3, title: "楚筑淮北之方城", summary: "防齐、秦之冲，筑城百里以守边。", detail: { background: "楚自陈徙寿春之议未决，淮北之地与齐、宋之故域相接。", process: "约前256年前后（楚考烈王二十五年筑城淮北之文，说者以其年与后此之徙都相校，二说并存）楚使春申君督其工，筑城于淮北以为备边之守，其役绵亘百里，故后世谓之方城。", impact: "淮北之守自此有恃，然楚之都邑随之东徙，根本之势不复在江汉；论楚亡国之缓急者每及此城与寿春之徙。", figures: ["春申君","楚考烈王"], place: "楚之淮北（今安徽北部）", state: "楚国", sources: ["《史记·春申君列传》","《史记·楚世家》","顾祖禹《读史方舆纪要》"], tags: ["方城","守备","春申君"] }, related: ["cn--b251--p01", "cn--b241--p02"] },
  { id: "cn--b256--s02", track: "cn", year: -256, yearApprox: true, dim: "science", weight: 4, title: "蜀守冰穿二江灌三郡", summary: "壅江起堋以辟离堆，水旱从人，蜀无凶年。", detail: { background: "江水出蜀之西山，其支流东注，旱则涸而潦则溢。", process: "约前256年前后（《华阳国志》以蜀守冰与张若并事，其年《史记》无明文，说者推定前后互异）秦之蜀守冰壅江起堋、穿二江以辟离堆，分为溉与运两道，旱则引水以灌，潦则泄归于江。", impact: "于是水旱从人，不知饥馑，蜀之沃野遂甲于西南；秦得顺江而下以图楚之巫、黔中，蜀为秦之南府。后世都江之堰迭有修治而其规实立于此。", figures: ["李冰","张若"], place: "蜀之湔堋与都江（今四川都江堰市西）", state: "秦国", sources: ["《史记·河渠书》","《华阳国志·蜀志》","《水经注·江水》"], tags: ["都江堰","水利","蜀郡"] }, related: ["cn--b246--s01", "cn--b316--i01"] },
  { id: "cn--b255--m01", track: "cn", year: -255, yearApprox: true, dim: "military", weight: 3, title: "燕相栗腹败于鄗", summary: "以赵为可乘而大举，两军俱败。", detail: { background: "赵自长平、邯郸再伤，燕以为可乘，乃以重币约欢而阴图之。", process: "前255年前后燕以栗腹将而攻鄗（今河北柏乡北），卿秦将而攻代；赵使廉颇将而拒之，一役而两军俱北，遂进围燕都，燕使使请和而倍其约。", impact: "燕之国力以是一蹶，赵虽起于疮痍而犹足以当其北冲；战国之论攻守，多以鄗之役为赵存之验。", figures: ["廉颇","栗腹","赵孝成王","燕王喜"], place: "赵之鄗、代与燕都（今河北柏乡、蔚县西南、北京）", state: "赵、燕", sources: ["《史记·廉颇蔺相如列传》","《史记·赵世家》","《史记·燕召公世家》"], tags: ["鄗","廉颇","燕赵"] }, related: ["cn--b269--m01", "cn--b251--p02"] },
  { id: "cn--b255--i01", track: "cn", year: -255, yearApprox: true, dim: "institution", weight: 2, title: "四公子之养士", summary: "尊贤下士，舍之人至数千人。", detail: { background: "魏有信陵、赵有平原、楚有春申、齐有孟尝，皆以礼士之名相先后。", process: "前255年前后四公子之门各致数千人，食客有上、中、下之别，其用或在辩说，或在技术，或在斗鸡狗马之戏；《史记》于孟尝、平原、信陵、春申各为之传，所以著战国养士之制。", impact: "舍人之多出而成私门之众，君主的权由是分损；合从之举赖以成，而齐、楚之亡亦或以士不用命为言。", figures: ["信陵君","平原君","春申君","孟尝君"], place: "大梁、邯郸、淮北与薛（今河南开封、河北邯郸、山东滕州）", state: "魏、赵、楚、齐", sources: ["《史记·魏公子列传》","《史记·平原君虞卿列传》","《史记·春申君列传》","《史记·孟尝君列传》"], tags: ["养士","门客","公子"] }, related: ["cn--b257--m01", "cn--b298--f01"] },
  { id: "cn--b251--p01", track: "cn", year: -251, yearApprox: false, dim: "politics", weight: 3, title: "春申君归楚立考烈王", summary: "黄歇与太子自秦亡归，太子遂立。", detail: { background: "楚顷襄王二十七年以太子完为质于秦，黄歇随之入秦；顷襄病而太子未得归。", process: "前251年黄歇诡其形橐以出太子于关，自留以谢罪；秦昭王怒，赖应侯为言得归其国，顷襄既薨而太子立，是为考烈王，以黄歇为令尹，封为春申君，委以国政。", impact: "令尹一人当国二十余年，楚之外交与徙都之议皆自其门出；其后李园之变亦由是局。", figures: ["春申君","楚考烈王","范雎","秦昭王"], place: "秦之咸阳、楚之郢陈（今陕西咸阳、河南淮阳）", state: "楚、秦", sources: ["《史记·春申君列传》","《史记·范雎蔡泽列传》","《史记·楚世家》"], tags: ["黄歇","令尹","徙质"] }, related: ["cn--b251--p02", "cn--b256--s03"] },
  { id: "cn--b251--p02", track: "cn", year: -251, yearApprox: false, dim: "politics", weight: 3, title: "赵以平原君约楚救", summary: "合从复成，楚救至而秦围乃解。", detail: { background: "邯郸之围解后赵之残破尤甚，乃以平原君为主从之约。", process: "前251年赵以平原君如楚与春申君定合从之约，楚出兵救赵；其后秦复取赵之梗阳等邑，赵不能拒而诸侯之救亦不复振。", impact: "从约虽复而诸侯之势终不能敌郡县之秦，合从之用自此仅存于一隅之救；平原君之为赵重亦由此定。", figures: ["平原君","春申君","楚考烈王","赵孝成王"], place: "赵之邯郸、楚之淮北（今河北邯郸、皖北）", state: "赵、楚", sources: ["《史记·平原君虞卿列传》","《史记·楚世家》","《史记·六国年表》"], tags: ["合从","平原君","楚赵"] }, related: ["cn--b258--p01", "cn--b251--p01"] },
  { id: "cn--b250--i01", track: "cn", year: -250, yearApprox: false, dim: "institution", weight: 2, title: "孝文王除租宽罚", summary: "即位之后除先王之租，宽薄罚而赦民。", detail: { background: "昭王末年刑罚益烦，山东新地之民苦于戍役与逋租。", process: "前250年秦孝文王即位，「除先王租于民，宽薄罚，赦山河之间杂寇」；其令行未几而王卒，庄襄王元年复有大赦之文。", impact: "以赦与除租收新附之民，为秦并地以后所以抚其民之常法；后此吕不韦「修先王之功，顺抚黔首」之政亦循此格。", figures: ["秦孝文王","秦庄襄王"], place: "秦都咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·秦本纪》","《史记·秦始皇本纪》","《睡虎地秦墓竹简》"], tags: ["赦令","赋租","秦制"] }, related: ["cn--b249--p02", "cn--b309--i01"] },
  { id: "cn--b249--p02", track: "cn", year: -249, yearApprox: false, dim: "politics", weight: 4, title: "吕不韦灭东周", summary: "东周君谋伐秦，不韦将而取其国，周祀遂尽。", detail: { background: "前256年西周君已举国入秦，赧王崩而周之祀止于阳人一路。", process: "前249年（秦庄襄王元年）东周君与诸侯谋伐秦，秦使相国吕不韦将而伐之；东周君入谢，因尽献其国，秦不复绝其祀，使处阳人以奉先祠。吕不韦食雒阳十万户，尊为仲父。", impact: "周之名分与器物自此尽归于秦，相邦得食洛阳之邑而都近之地皆入郡县；后此九年并六国之谋即成于是局。", figures: ["吕不韦","秦庄襄王","东周君"], place: "周之河南、阳人（今河南洛阳、伊川一带）", state: "周、秦", sources: ["《史记·秦本纪》","《史记·周本纪》","《史记·吕不韦列传》"], tags: ["东周","吕不韦","九鼎"] }, related: ["cn--b256--p01", "cn--b249--i01"] },
  { id: "cn--b249--i01", track: "cn", year: -249, yearApprox: true, dim: "institution", weight: 3, title: "秦初置三川郡", summary: "取成皋、荥阳之后，以河南为郡而置守。", detail: { background: "韩之成皋、荥阳既拔，河内、河南与三川之会尽为秦土。", process: "前249年前后（《秦本纪》与《秦始皇本纪》分系两代，故年从约）秦初置三川郡，治雒阳，以三川为名而县隶焉；郡置守、尉，县置令、长，其官皆由中除。", impact: "三川当天下之冲，漕运与车轨由此东出；秦所置诸郡渐成程式，后此并天下而为三十六郡之张本。", figures: ["蒙骜","吕不韦"], place: "秦三川郡（治雒阳，今河南洛阳）", state: "秦国", sources: ["《史记·秦本纪》","《汉书·地理志》","《史记·秦始皇本纪》","顾祖禹《读史方舆纪要》"], tags: ["郡县","三川","官制"] }, related: ["cn--b249--p02", "cn--b272--i01"] },
  { id: "cn--b247--p01", track: "cn", year: -247, yearApprox: false, dim: "politics", weight: 4, title: "秦王政立，国事决于相邦", summary: "年十三而即位，尊吕不韦为仲父。", detail: { background: "庄襄王以吕不韦之力得立，故即位而委国焉。", process: "前247年庄襄王薨而太子政立，年十三；尊相邦吕不韦为仲父，军国之事皆决于相府，门下一千人，家僮万人。是岁晋阳有反者，秦使蒙骜定之。", impact: "王幼而相权重，五年之间而有嫪毐之乱与免相之文；秦之并天下虽成于政，而其始则在相邦之府。", figures: ["秦始皇","吕不韦","秦庄襄王"], place: "秦都咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·秦始皇本纪》","《史记·吕不韦列传》"], tags: ["秦王政","仲父","幼立"] }, related: ["cn--b238--p01", "cn--b239--c01"] },
  { id: "cn--b247--m01", track: "cn", year: -247, yearApprox: true, dim: "military", weight: 4, title: "五国之兵却秦于河外", summary: "信陵君将诸侯之师，追败秦军至函谷关。", detail: { background: "秦数使蒙骜伐魏，魏王患之，乃起信陵君于赵而将上将军之任。", process: "前247年前后公子无忌使人请救于诸侯，五国之兵皆至，与秦战于河外，蒙骜败走；诸侯之师乘胜追至函谷关，秦人闭城不敢出。", impact: "秦之东出为此中止者十余年，魏得少安；然无忌旋以谗废而卒，合从之局遂不复振，魏之亡亦在二十年之内。", figures: ["信陵君","蒙骜","魏安釐王"], place: "魏之河外与函谷关（今豫西、陕西灵宝）", state: "魏、秦", sources: ["《史记·魏公子列传》","《史记·秦本纪》","《史记·魏世家》"], tags: ["河外","合从","信陵君"] }, related: ["cn--b257--m01", "cn--b243--d01"] },
  { id: "cn--b246--s01", track: "cn", year: -246, yearApprox: false, dim: "science", weight: 4, title: "郑国渠成，关中无凶年", summary: "引泾东注，溉卤四万余顷，亩收一锺。", detail: { background: "韩数困于秦，欲以巨役罢其力，乃使水工郑国间说秦令穿渠。", process: "前246年起，凿泾水自中山西邸瓠口而东，注洛三百余里，欲以灌卤；中而觉，秦欲杀之，国曰「始臣为间，然渠成亦秦之利也」，卒使完之。凡数岁而渠成，溉泽卤之地四万余顷，皆亩一锺；《河渠书》著其顷亩与所注洛之水程，其数与古今度量不可相校，说者不能一其解。", impact: "关中自是为沃野而无凶年，秦以是富强而卒并诸侯；韩之疲秦适以资秦，而郑、白二渠遂为后世引泾、引渭者所取法。", figures: ["郑国","秦庄襄王","秦始皇"], place: "秦之泾、洛之间（今陕西泾阳至大荔一带）", state: "秦国", sources: ["《史记·河渠书》","《汉书·沟洫志》","《史记·秦始皇本纪》"], tags: ["郑国渠","水利","关中"] }, related: ["cn--b256--s02", "cn--b247--p01"] },
  { id: "cn--b245--a01", track: "cn", year: -245, yearApprox: true, dim: "art", weight: 2, title: "丛台与高台之观", summary: "连聚非一，台榭之制至战国而极盛。", detail: { background: "春秋之世台用以望气与游观，战国诸侯竞为高台榭、美宫室。", process: "前245年前后（依遗构与传说推定，赵丛台之筑《史记》无明文）赵都邯郸之丛台联聚非一，台上有观、有射者之场；齐之渐台、楚之章华与魏之繁台并其类，皆以土与木累而为台，覆以瓦当。", impact: "台榭之制既盛，则登临、射御与钟鼓之乐随之，故诸子有台榭是虞之戒；战国宫室之遗制与瓦当文字多自此中见之。", figures: ["赵武灵王","楚灵王"], place: "赵都邯郸（今河北邯郸丛台一带）", state: "赵、齐、楚", sources: ["《史记·赵世家》","《国语·楚语上》（章华之台）","《邯郸县志》丛台之目","宿白《中国建筑史》论台榭诸节"], tags: ["台榭","建筑","瓦当"] }, related: ["cn--b307--m02", "cn--b279--p01"] },
  { id: "cn--b243--d01", track: "cn", year: -243, yearApprox: false, dim: "disaster", weight: 2, title: "蝗飞蔽天而至秦", summary: "东方之蝗入秦界，是岁得民买爵之令。", detail: { background: "秦之关中本仰泾、渭之灌，蝗自山东来则田禾尽去。", process: "前243年（秦王政四年）蝗从东方来，飞蔽天而至秦；是岁秦令民得买爵，说者谓因饥馑而设。所损之顷亩与流殍之数，史不书其数。", impact: "大灾而不辍兵，岁有新城之役，秦之调发不以荒岁为忌；入粟拜爵之法行于秦，可见其荒政之制。", figures: ["秦始皇"], place: "秦之关中与山东之地（今陕西中部、太行以东）", state: "秦国", sources: ["《史记·秦始皇本纪》","《汉书·五行志》","马端临《文献通考·物异考》"], tags: ["蝗灾","荒政","买爵"] }, related: ["cn--b242--m01", "cn--b247--m01"] },
  { id: "cn--b242--m01", track: "cn", year: -242, yearApprox: false, dim: "military", weight: 2, title: "蒙骜攻韩取十一城", summary: "秦岁东伐韩，诸侯之救不复至。", detail: { background: "韩自野王、南阳再失，惟余荥阳、新郑之间数城。", process: "前242年秦将军蒙骜攻韩，取十一城（《秦始皇本纪》书其数，所拔城名史不尽载）；韩不能拒，而五国之救以信陵君既死不至。", impact: "韩之邑日削而势不可支，遂成秦之「一郡」；其後八年而虏王安，即此役之渐。", figures: ["蒙骜","韩安王"], place: "韩之南阳、荥阳间（今河南中部）", state: "秦、韩", sources: ["《史记·秦始皇本纪》","《史记·韩世家》","《史记·六国年表》"], tags: ["攻韩","城邑","韩亡"] }, related: ["cn--b230--p01", "cn--b241--m01"] },
  { id: "cn--b241--m01", track: "cn", year: -241, yearApprox: false, dim: "military", weight: 4, title: "五国攻秦，军败于蕞", summary: "最后一次合纵，至蕞而诸侯之师退。", detail: { background: "楚、魏新与秦绝，赵数困于秦，合从之议复起，楚考烈王主之。", process: "前241年楚、赵、魏、韩、燕五国共伐秦，东至蕞（今陕西临潼北），去咸阳不远；秦出兵击之，诸侯之军败而退走，秦乘胜东取其地而罢。", impact: "此后山东不复有合兵西向之举，秦之东出惟择时而掳其王；战国之合纵至蕞之役而终。", figures: ["楚考烈王","春申君","赵悼襄王","秦始皇"], place: "秦之蕞与关东（今陕西临潼北）", state: "楚、赵、秦", sources: ["《史记·秦始皇本纪》","《史记·楚世家》","《史记·赵世家》","《史记·春申君列传》"], tags: ["蕞","合纵","最后"] }, related: ["cn--b241--p02", "cn--b242--m01"] },
  { id: "cn--b241--p02", track: "cn", year: -241, yearApprox: false, dim: "politics", weight: 3, title: "楚徙都寿春，号春申君", summary: "去淮北方城，东保吴、越之饶。", detail: { background: "淮北之地方数千里而迫于秦之东郡，楚之陈已不足守。", process: "前241年楚与诸侯攻秦不胜，乃徙都寿春（今安徽寿县），仍号春申君之国；春申君于是时且劝考烈王以观秦之变，其策「毋近秦而收东方」之说不行。", impact: "楚之东徙去其江汉之本，吴、越之饶不复能救其政令之散；后八年秦取荆地而楚遂亡。", figures: ["楚考烈王","春申君","李园"], place: "楚之寿春（今安徽寿县）", state: "楚国", sources: ["《史记·楚世家》","《史记·春申君列传》","《史记·秦始皇本纪》"], tags: ["寿春","徙都","楚国"] }, related: ["cn--b256--s03", "cn--b223--m01"] },
  { id: "cn--b240--s01", track: "cn", year: -240, yearApprox: false, dim: "science", weight: 2, title: "彗星先出东方", summary: "七星之纪见于秦历，将帅之卒并书。", detail: { background: "秦以颛顼历纪日，其官有司历、司星之职，星变亦书于纪。", process: "前240年（秦王政七年）「彗星先出东方，见北方，五月见西方」（《秦始皇本纪》）；是岁将军蒙骜卒，纪载并及之。说者以其星为后世周期彗星记录之所自，然名目与轨道之推定出于近世，不能与古书之辞相合。", impact: "战国秦国之纪事已有天文一门，后汉志所本；自是而历与星占同出史官，其书之体例遂为后世所承。", figures: ["秦始皇","蒙骜"], place: "秦之咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·秦始皇本纪》","《晋书·天文志》","《汉书·五行志》"], tags: ["彗星","天文记录","历法"] }, related: ["cn--b268--s01", "cn--b241--m01"] },
  { id: "cn--b239--c01", track: "cn", year: -239, yearApprox: true, dim: "culture", weight: 5, title: "《吕氏春秋》成书", summary: "八览六论十二纪，二十余万言悬市门。", detail: { background: "吕不韦以商贾入相，尊为仲父，乃集门下宾客各著所闻，以备天地万物古今之事。", process: "前239年前后（成书之岁据《序意》「维秦五月，日在聚吕」之文推定，说者于前239与前235之间不一，故从约）其书成，为十二纪、八览、六论，凡二十余万言；不韦延诸侯游士宾客于咸阳门市，称有能增损一字者予千金。", impact: "其书兼载儒、墨、名、法与四时之政，后世谓之杂家；十二纪之文后入《礼记·月令》，可见战国末学术之合流与秦之将并天下也。", figures: ["吕不韦"], place: "秦都咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·吕不韦列传》","《吕氏春秋·序意》","高诱《吕氏春秋注》","许维遹《吕氏春秋集释》"], tags: ["吕氏春秋","杂家","著述"] }, related: ["cn--b247--p01", "cn--b237--p01"] },
  { id: "cn--b238--p01", track: "cn", year: -238, yearApprox: false, dim: "politics", weight: 4, title: "王冠，遂亲国事", summary: "冠于雍，因幸其宫；长信侯因得矫王御玺。", detail: { background: "秦王政以幼立，国事决于相邦；九年将冠，例当亲庙。", process: "前238年秦王冠，因幸雍之祈年宫、棫阳宫；长信侯嫪毐窃其王玺与太后之玺，发县卒与骑以作乱，将以攻宫。王觉，使相国与昌平君、昌文君发兵距之。", impact: "自是王亲览政事，太后之权与嫪毐之门俱尽，相邦之势亦随之而摇；三年而有免不韦之文。", figures: ["秦始皇","嫪毐","吕不韦","昌平君"], place: "秦之雍（今陕西凤翔南）", state: "秦国", sources: ["《史记·秦始皇本纪》","《史记·吕不韦列传》","《史记·秦始皇本纪》集解引徐广"], tags: ["冠礼","亲政","嫪毐"] }, related: ["cn--b238--m01", "cn--b247--p01"] },
  { id: "cn--b238--m01", track: "cn", year: -238, yearApprox: false, dim: "military", weight: 4, title: "嫪毐之乱平", summary: "战于咸阳之下，获毐而车裂，夷其三族。", detail: { background: "毐以太后之故得封山阳之地，乘王在外，矫玺而发卒。", process: "前238年两战于咸阳之下，乱众败走，毐既而见获，车裂以徇，夷其三族；所斩与溺死之数《秦始皇本纪》与《吕不韦列传》多寡不侔，故不取一定之数。宦者、令长之坐者各夺爵而迁蜀，太后迁于雍。", impact: "以外幸之人与宫闱之变而兴兵，一败而枝叶尽去；秦之权自此不出于后、不出于相，而独归于王。", figures: ["嫪毐","秦始皇","昌文君"], place: "咸阳、雍（今陕西咸阳、凤翔）", state: "秦国", sources: ["《史记·秦始皇本纪》","《史记·吕不韦列传》","《战国策·秦策》"], tags: ["嫪毐","内乱","车裂"] }, related: ["cn--b238--p01", "cn--b237--p01"] },
  { id: "cn--b237--p01", track: "cn", year: -237, yearApprox: true, dim: "politics", weight: 4, title: "逐客令与李斯谏书", summary: "大索而逐客，斯上书乃止其令。", detail: { background: "嫪毐之党有他国之人，秦吏因请尽逐客卿以清其源。", process: "前237年前后（《本纪》与《李斯列传》所系先后微异，故从约）秦下逐客之令，李斯在逐中，乃上书言「太山不让土壤，故能成其大；河海不择细流，故能就其深」，历数穆公、孝公、惠文、昭王用客之效；王乃止逐客令，复用斯，其后官至廷尉。", impact: "客卿之制由是复行，秦之并天下也，李斯、尉缭之徒与有力焉；此书遂为战国处士流动之最著文字。", figures: ["李斯","秦始皇"], place: "秦都咸阳（今陕西咸阳东北）", state: "秦国", sources: ["《史记·李斯列传》","《史记·秦始皇本纪》","钱穆《先秦诸子系年》"], tags: ["客卿","逐客令","李斯"] }, related: ["cn--b237--f01", "cn--b239--c01"] },
  { id: "cn--b237--f01", track: "cn", year: -237, yearApprox: true, dim: "figure", weight: 3, title: "韩非使秦，李斯荐其对", summary: "韩非以《孤愤》《五蠹》书至秦，王读而善之。", detail: { background: "韩非者韩之诸公子，见韩之日削，乃著《孤愤》《五蠹》内外储、说林、说难十余万言。", process: "前237年前后（入秦之岁《史记》两传与《战国策》互异，故从约）其书入秦，秦王政读之曰「嗟乎，寡人得见此人与之游，死不恨矣」，因急攻韩以求其使；非至，说难之行未获用。", impact: "法、术、势之说自此入于秦廷；其后秦之治不师古、不别亲疏者，多与非书相表里，而其言亦为汉以后之论者所不及。", figures: ["韩非","秦始皇"], place: "韩之新郑与秦之咸阳（今河南新郑、陕西咸阳）", state: "韩、秦", sources: ["《史记·老子韩非列传》","《韩非子·五蠹》","《韩非子·孤愤》","陈奇猷《韩非子集释》"], tags: ["韩非","法术势","著述"] }, related: ["cn--b237--p01", "cn--b234--f01"] },
  { id: "cn--b236--m01", track: "cn", year: -236, yearApprox: false, dim: "military", weight: 3, title: "秦取赵阏与、邺", summary: "王翦、桓齮、杨端三将拔九城，赵救不及。", detail: { background: "赵自悼襄以来数与燕争，西边之备反疏；秦乃择地而攻。", process: "前236年秦使王翦、桓齮、杨端和攻赵之阏与、轵、杨涉，取邺与九城；赵以庞煖将而救邺，会霖雨而军不得进，秦卒有其地。", impact: "秦之东郡与赵之河北由此相接，赵之南北中断；后四年而王翦出井陉，即自此道。", figures: ["王翦","桓齮","杨端和","庞煖","赵悼襄王"], place: "赵之阏与、邺（今山西和顺、河北临漳西）", state: "秦、赵", sources: ["《史记·秦始皇本纪》","《史记·赵世家》","《史记·廉颇蔺相如列传》"], tags: ["邺","阏与","分进"] }, related: ["cn--b229--m01", "cn--b270--m01"] },
  { id: "cn--b235--p01", track: "cn", year: -235, yearApprox: false, dim: "politics", weight: 3, title: "文信侯就国河南", summary: "免相而出，诸侯使使者趋之，乃有召让之文。", detail: { background: "嫪毐之狱连及相邦，王以未忍诛，但免其相位。", process: "前235年（《本纪》作十年，列传次序与之小异）秦免相国文信侯吕不韦，就国河南，宾客使者车乘相望于道；王恐其变，使使让之曰「君何功于秦，而君万乘？何亲于秦，而称为仲父」，召之迁蜀。不韦自知诛在即，乃饮酖而死；宾客窃葬其于洛阳北芒之东，坐者迁之。", impact: "自商鞅、张仪、范雎以来客卿为相者之局至此而结；「奇货可居」之说亦遂为后世论市道与国事相因者之口实。", figures: ["吕不韦","秦始皇"], place: "河南之雒阳与蜀之徙所（今河南洛阳、四川）", state: "秦国", sources: ["《史记·吕不韦列传》","《史记·秦始皇本纪》"], tags: ["吕不韦","免相","客卿"] }, related: ["cn--b249--p02", "cn--b239--c01"] },
  { id: "cn--b234--f01", track: "cn", year: -234, yearApprox: true, dim: "figure", weight: 3, title: "韩非死于云阳", summary: "下吏，李斯、姚贾短之，使持药，非自杀。", detail: { background: "非为韩而难言于秦，或短之曰「韩非终不为秦，不如以法绳而过而杀之」。", process: "前234年前后（一说在翌年，两传与年表所载互异，故从约）秦使吏治非，李斯使人遗之药，使自杀；韩非欲自明而不得见，遂死云阳。秦王悔，使人赦之，则已及矣。", impact: "法家之言与用法之人同出于一时，而其相倾如此；《说难》之书所以自状其忧，后世读之，以为非死于书之验。", figures: ["韩非","李斯","姚贾","秦始皇"], place: "秦之云阳（今陕西淳化西北）", state: "韩、秦", sources: ["《史记·老子韩非列传》","《史记·秦始皇本纪》","《韩非子·说难》"], tags: ["韩非","云阳","法家"] }, related: ["cn--b237--f01", "cn--b237--p01"] },
  { id: "cn--b234--i01", track: "cn", year: -234, yearApprox: true, dim: "institution", weight: 2, title: "初令男子书年", summary: "男各书其年于籍，傅役始于有据。", detail: { background: "古之傅籍有年而无定制，战国征发益繁，年名乃须核。", process: "前234年（《秦始皇本纪》系之十四年，说者有谓当作初令之年者，故从约）秦初令男子书年，各占其名年于县；后此傅籍、免老之制皆以是为本，睡虎地所出秦律于年、长有程验之条。", impact: "年与名入于官簿，征发、赏罚始有可案之文；论战国户籍之制者以此条为切证，汉之名年亦承其格。", figures: ["秦始皇"], place: "秦之郡县（今陕西、河南）", state: "秦国", sources: ["《史记·秦始皇本纪》","睡虎地秦墓竹简整理小组《睡虎地秦墓竹简》","《汉书·食货志》"], tags: ["户籍","傅籍","秦律"] }, related: ["cn--b348--i01", "cn--b249--i01"] },
  { id: "cn--b233--m01", track: "cn", year: -233, yearApprox: false, dim: "military", weight: 2, title: "桓齮取赵赤丽、幽都", summary: "又攻宜安，为李牧所破，河北之兵久连。", detail: { background: "秦自取邺之后，别遣将略赵之河北，赵数困而未尝受大创。", process: "前233年桓齮将而南，取赵之赤丽、幽都；宜安之役赵以李牧拒之，秦师败。两役之先后与牧之官号，《秦本纪》、《廉颇蔺相如列传》、《赵世家》所载互异，所获之数故不书。", impact: "秦、赵之兵连于河北者累年，赵所赖以支者独李牧一军；秦之欲下赵，必先去牧而后可以言兵。", figures: ["桓齮","李牧","赵王迁"], place: "赵之赤丽、幽都、宜安（今河北藁城、晋州一带）", state: "秦、赵", sources: ["《史记·秦始皇本纪》","《史记·廉颇蔺相如列传》","《史记·赵世家》"], tags: ["幽都","宜安","李牧"] }, related: ["cn--b229--m01", "cn--b236--m01"] },
  { id: "cn--b232--e01", track: "cn", year: -232, yearApprox: true, dim: "economy", weight: 2, title: "半两与布钱并行", summary: "以钱当布，市有常平；关市有征而市籍有程。", detail: { background: "秦之圜钱曰半两，其行已早；山东之地犹或用刀、用布。", process: "前232年前后（秦铸半两之始岁无明文，此据新得之地与律文推定）秦以半两为上币，而以布为下币，布、钱相准而行于市；睡虎地所出《金布律》有布与钱相当、市贾平其值之条，又有关市有征之令。", impact: "币制之通一行于郡县之中，商贾之利与征商之权同隶于官；后此并天下而一币制者，其程式实成于战国之末。", figures: ["秦始皇"], place: "秦之关中与新得之郡（今陕西、河南）", state: "秦国", sources: ["睡虎地秦墓竹简整理小组《睡虎地秦墓竹简·金布律》","《史记·平准书》","《汉书·食货志》"], tags: ["半两","货币","关市"] }, related: ["cn--b336--e01", "cn--b249--i01"] },
  { id: "cn--b231--p01", track: "cn", year: -231, yearApprox: true, dim: "politics", weight: 3, title: "秦以河内易安邑之民", summary: "与魏相易，尽取安邑而徙其民于秦。", detail: { background: "魏之河东旧地本以赂秦而去，其民多故魏之世族。", process: "前231年秦与魏会，请以河东之地与魏相易，因取魏之安邑而徙其安邑之民；魏之守令无所复施，河东尽为秦之县邑。易与迁之先后两传微异，故系年从约。", impact: "秦之东面自此与河内、三川相贯，得故都之民而实其新地；魏以虚地易实民，其国势遂不可支。", figures: ["魏王假","秦始皇"], place: "魏之河东安邑（今山西夏县西北）", state: "秦、魏", sources: ["《史记·秦始皇本纪》","《史记·魏世家》","《史记·六国年表》"], tags: ["河东","徙民","魏亡"] }, related: ["cn--b230--p01", "cn--b330--p01"] },
  { id: "cn--b230--p01", track: "cn", year: -230, yearApprox: false, dim: "politics", weight: 5, title: "内史腾虏韩王安", summary: "韩举国入秦，以其地置颍川郡。", detail: { background: "韩自南阳、河内再失，惟余阳翟、新郑之间；秦使内史掌兵以临之。", process: "前230年秦使内史腾击韩，虏韩王安，尽取其国；以其地为颍川郡，置守、尉而县其邑。韩之先为晋之别封，其后为七雄之一，凡数百年而亡于秦。", impact: "六国之亡自此始，秦得颍川则楚、赵之冲背腹受敌；策士所谓「韩亡而赵、魏不支」之说，至是验于事实。", figures: ["内史腾","韩安王","秦始皇"], place: "韩之阳翟、新郑（今河南禹州、新郑）", state: "秦、韩", sources: ["《史记·秦始皇本纪》","《史记·韩世家》","《史记·六国年表》"], tags: ["灭韩","颍川郡","郡县"] }, related: ["cn--b229--m01", "cn--b242--m01"] },
  { id: "cn--b229--m01", track: "cn", year: -229, yearApprox: false, dim: "military", weight: 4, title: "秦出井陉，李牧以反间死", summary: "王翦、杨端和两路入赵，牧被谗而不受命。", detail: { background: "赵自幽文、哀襄以来国势益蹙，所恃惟李牧、司马尚之军。", process: "前229年秦兴两路之师，一出井陉，一循邺、漳以临赵；赵使李牧、司马尚距之，秦不能下。乃多与赵之宠臣郭开金，使为反间，言牧与尚欲为变；赵王使赵葱、颜聚代将，牧以将在军不受命为对，遂捕诛牧而废尚。", impact: "赵之最后的支柱去，三个月而都破；战国之以反间亡其将者，前后数事而此最著，论将帅之任与用人之察者恒以为戒。", figures: ["李牧","郭开","王翦","赵王迁","司马尚"], place: "井陉、肥累与邯郸（今河北井陉、藁城、邯郸）", state: "秦、赵", sources: ["《史记·廉颇蔺相如列传》","《史记·秦始皇本纪》","《史记·赵世家》","《韩非子》论用间诸篇"], tags: ["反间","李牧","井陉"] }, related: ["cn--b228--m01", "cn--b233--m01"] },
  { id: "cn--b228--m01", track: "cn", year: -228, yearApprox: false, dim: "military", weight: 5, title: "王翦虏赵王迁", summary: "军破赵葱，遂入邯郸，迁见虏。", detail: { background: "牧既死，赵葱、颜聚当军，众不附而士疑。", process: "前228年王翦急击赵，大破之，杀赵葱，颜聚亡走；秦军遂入邯郸，虏赵王迁。赵之先与秦同出自蜚廉之裔，其世系与立国之始详于《赵世家》，至此而国除。", impact: "赵自武灵王胡服、惠文守成以来百年之基，亡于长平创后之十余年；秦得河北诸郡，燕之南蔽亦去，荆轲之计由是而起。", figures: ["王翦","赵王迁","赵葱","桓齮"], place: "赵都邯郸（今河北邯郸）", state: "秦、赵", sources: ["《史记·秦始皇本纪》","《史记·白起王翦列传》","《史记·赵世家》"], tags: ["灭赵","邯郸","郡县"] }, related: ["cn--b229--m01", "cn--b227--p01"] },
  { id: "cn--b228--x01", track: "cn", year: -228, yearApprox: true, dim: "explore", weight: 2, title: "赵嘉王代，北边郡县之人南徙", summary: "大夫数立嘉为王，保代、云中以北。", detail: { background: "赵之都既陷，其北边云中、雁门、代之守令各以其地降于秦。", process: "前228年前后赵之群臣立宜太子嘉为代王，收北边之众数千，南拒燕、西备胡，保上谷、渔阳以北之地；秦之郡县渐定于太行以东，代遂为残绪之邦。", impact: "赵武灵王以来西北边郡之建置至此入秦，云中、雁门之民遂为守塞之卒；论战国北边郡县之成者以赵之代为末节。", figures: ["赵嘉","赵王迁"], place: "代之南北（今河北蔚县、山西代县一带）", state: "代、赵", sources: ["《史记·赵世家》","《史记·匈奴列传》","《汉书·地理志》","顾祖禹《读史方舆纪要》"], tags: ["代郡","北边","残余"] }, related: ["cn--b228--m01", "cn--b222--m01"] },
  { id: "cn--b227--p01", track: "cn", year: -227, yearApprox: false, dim: "politics", weight: 4, title: "荆轲刺秦王不中", summary: "奉樊於期之首与督亢地图，图穷而匕首见。", detail: { background: "燕太子丹以秦并赵兵已就，患其北渡，与鞠武、田光谋所以距秦者，轲以辩士得进。", process: "前227年荆轲入秦，先以樊於期之首与燕之督亢地图为贽；秦王召见，发图而图穷、匕首见，左手把其袖而右手揕抗之，不中；王惊起，袖绝，左右共杀轲于殿下。", impact: "以劫盟之谋而激秦之怒，秦大举攻燕，蓟遂不守；战国刺客之传自此入正史，而燕之亡亦止五年之间。", figures: ["荆轲","燕太子丹","秦始皇","樊於期","田光"], place: "秦之咸阳宫、燕之督亢（今陕西咸阳、河北涿州一带）", state: "燕、秦", sources: ["《史记·刺客列传》","《战国策·燕策三》","《史记·秦始皇本纪》","《史记·燕召公世家》"], tags: ["荆轲","刺秦","督亢"] }, related: ["cn--b227--a01", "cn--b226--m01"] },
  { id: "cn--b227--a01", track: "cn", year: -227, yearApprox: false, dim: "art", weight: 2, title: "易水之送与变徵之音", summary: "高渐离击筑，为变徵之声，士皆垂泪。", detail: { background: "燕之市人高渐离善击筑，与荆轲相善，每饮于市而相和而歌。", process: "前227年轲之发也，太子丹及宾客知其事者皆白衣冠以送之于易水之上；渐离击筑，轲和而歌，为变徵之声，士皆垂泪，又为慷慨羽声，目皆裂。乃遂就车而去，终已不顾。", impact: "一段送别之辞遂为后世言燕赵多慷慨之声者所本；筑与歌相和之制，亦可见战国末燕都乐工之盛。", figures: ["荆轲","高渐离","燕太子丹"], place: "燕之易水（今河北易县一带）", state: "燕国", sources: ["《史记·刺客列传》","《战国策·燕策三》","《乐府诗集》论燕声诸说"], tags: ["易水","筑","送别"] }, related: ["cn--b227--p01", "cn--b226--m01"] },
  { id: "cn--b226--m01", track: "cn", year: -226, yearApprox: false, dim: "military", weight: 3, title: "王翦拔蓟，燕王徙辽东", summary: "斩太子丹以献，遂东渡而保辽东。", detail: { background: "轲之事觉，秦大怒，使王翦与将北攻燕；其将与燕拒于易水之西，燕不能支。", process: "前226年秦军克燕都蓟，得太子丹；燕王喜乃东渡，保辽东，斩丹以献于秦而求缓师。赵之故太子嘉亦奔代，赵、燕之残绪相连于北边。", impact: "燕以亡其都而守辽东，地虽远而民力尽；秦于辽东之兵后此五年乃下，战国之北边至此略定。", figures: ["王翦","燕王喜","燕太子丹"], place: "燕都蓟与辽东（今北京、辽宁辽阳一带）", state: "燕、秦", sources: ["《史记·秦始皇本纪》","《史记·燕召公世家》","《史记·白起王翦列传》"], tags: ["蓟","辽东","徙都"] }, related: ["cn--b227--p01", "cn--b222--m01"] },
  { id: "cn--b225--p01", track: "cn", year: -225, yearApprox: false, dim: "politics", weight: 3, title: "秦王问数：李信二十万", summary: "以为荆易得，师少而败于城父。", detail: { background: "秦既灭韩、破赵、亡魏，将谋伐荆而问众数于其群臣。", process: "前225年李信以二十万为不足多，王翦必欲六十万而后办；王以翦为老而怯于众，乃以信与蒙恬南攻，初取其平舆、寝与郢陈，楚因项燕之军随而大破之，入垒而秦两都尉死。", impact: "秦之并天下惟此役尝一败，其失在计众之疏；王翦六十万之说自此见听，战国末之兵事已非举国不可为。", figures: ["李信","王翦","蒙恬","项燕","秦始皇"], place: "楚之平舆、寝与陈（今河南平舆、安徽临泉、淮阳）", state: "秦、楚", sources: ["《史记·白起王翦列传》","《史记·秦始皇本纪》","《史记·楚世家》"], tags: ["伐荆","李信","众数"] }, related: ["cn--b224--m01", "cn--b223--m01"] },
  { id: "cn--b224--m01", track: "cn", year: -224, yearApprox: false, dim: "military", weight: 4, title: "王翦以六十万坚壁破荆", summary: "日休士与戏，楚引而去，追而大破之。", detail: { background: "秦以李信之败乃自往请王翦，许以六十万而后的行。", process: "前224年翦将六十万入楚，坚壁而不应楚之挑战，日休士与之为戏而抚循之；荆之众数挑战不得，乃引而去，翦随而击之，大败楚军，项燕死于是役，昌平君亦败亡。二将之死处与先后，《本纪》与《列传》互异，故不名一地。", impact: "以逸待劳之效见于举国之兵，荆之锐遂尽；后一岁而虏其王，楚之亡不以其地之广与众之多得免。", figures: ["王翦","项燕","昌平君","秦始皇"], place: "蕲与平舆之间（今安徽宿州、河南平舆）", state: "秦、楚", sources: ["《史记·白起王翦列传》","《史记·秦始皇本纪》","《史记·楚世家》","钱穆《先秦诸子系年》附考楚世诸说"], tags: ["灭楚","坚壁","项燕"] }, related: ["cn--b223--m01", "cn--b225--p01"] },
  { id: "cn--b223--e01", track: "cn", year: -223, yearApprox: true, dim: "economy", weight: 2, title: "楚亡后的江南之饶", summary: "稻、纻、旄竹与金、革、羽、丹之利入秦。", detail: { background: "楚之故地江、淮以南，本以稻、鱼、纻、竹之利与铜、锡之矿为天下饶。", process: "前223年前后（楚亡之岁江南之郡县犹未全定，故从约）楚之淮北、江南与吴、越之故地入于秦，衡山、长沙之积与豫章之木材、丹铜、羽齿之属始通于北贾；邯郸之织、齐之丝与楚之纻并为山东之货。", impact: "南方之物产自此入于北方之市，谪戍与徙民实其地，而会稽、长沙之郡名后皆缘此而立；论秦汉之际江东之富者每原于战国末之交通。", figures: ["秦始皇"], place: "楚之江南与吴越故地（今湖南、江西、江苏南部）", state: "秦", sources: ["《史记·货殖列传》","《史记·秦始皇本纪》","《汉书·地理志》"], tags: ["江南","物产","徙民"] }, related: ["cn--b223--m01", "cn--b306--x01"] },
  { id: "cn--b222--m01", track: "cn", year: -222, yearApprox: false, dim: "military", weight: 4, title: "秦虏燕王喜与代王嘉", summary: "辽东、代二地俱入于秦，燕、赵皆除。", detail: { background: "燕自去其故都，与赵之残众各保辽东、代北，约相为援。", process: "前222年秦大兴兵，使王贲将而北取燕之辽东，虏燕王喜；还师击代，虏代王嘉，赵之宗祀至此亦绝。燕之先与周同姓，其封于召公者至此七百余年而亡。", impact: "燕、赵之邦既尽，齐以不设备之故不能自立于其东，并天下之局至此已成；而辽东入于郡，中国之北塞与东海外之交亦自是而开。", figures: ["王贲","燕王喜","赵嘉","秦始皇"], place: "辽东与代（今辽宁辽阳一带、河北蔚县）", state: "秦", sources: ["《史记·秦始皇本纪》","《史记·燕召公世家》","《史记·赵世家》","《史记·六国年表》"], tags: ["灭燕","代王嘉","辽东"] }, related: ["cn--b226--m01", "cn--b228--x01"] },
];
